window.__AI4S_API__.articleDetails=Object.assign(window.__AI4S_API__.articleDetails||{},{"report-org-talent":{"id":5,"slug":"report-org-talent","title":"组织与人才：AI4S 正在改写高校的科研建制","kind":"report","dek":"北大科学智能学院的实体建制与双导师制、复旦 AI3 “研究机构运营算力平台”的模式、浙大的圈层式协同中心、复旦 AI-BEST 四层课程与“AI 不是味精而是主料”的判断——以及考核归属这个最难解的问题。","tags":["科学智能学院","AI+Science 双导师制","AI-BEST 课程体系","交叉学科中心","产学研协同","人工智能+教育行动计划"],"sources":[{"url":"https://lygw.ai/blog/20250904-ai4s/","date":"2025-09-04","site":"lygw.ai","title":"国内高校 AI4S 实践凝练与洞察：从“范式革命”到“务实深耕”"},{"url":"https://www.edu.cn/ke_yan_yu_fa_zhan/expert/202604/t20260427_2730880.shtml","date":"2026-04-27","site":"中国教育和科研计算机网 CERNET","title":"复旦大学校长金力院士：培养人工智能交叉创新人才，激发高校创新活力"},{"url":"https://baike.baidu.com/item/%E5%A4%8D%E6%97%A6%E5%A4%A7%E5%AD%A6%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E5%88%9B%E6%96%B0%E4%B8%8E%E4%BA%A7%E4%B8%9A%E7%A0%94%E7%A9%B6%E9%99%A2/67215627","date":"2026-08-18","site":"百度百科","title":"复旦大学人工智能创新与产业研究院"},{"url":"https://news.pkusz.edu.cn/info/1002/9271.htm","date":"2025-09-05","site":"南燕新闻网","title":"北京大学深圳研究生院上线『AI4S LAB』"},{"url":"https://baike.baidu.com/item/%E4%B8%8A%E6%B5%B7%E7%A7%91%E5%AD%A6%E6%99%BA%E8%83%BD%E7%A0%94%E7%A9%B6%E9%99%A2/64511802","date":"2026-09-04","site":"百度百科","title":"上海科学智能研究院"},{"url":"http://smse.whut.edu.cn/xydt/202608/t20260814_1413959.shtml","date":"2026-08-14","site":"武汉理工大学材料科学与工程学院","title":"腾讯云来院开展 AI for Science 合作交流"},{"url":"https://uc.whu.edu.cn/info/1646/118851.htm","date":"2025-03-04","site":"武汉大学本科生院","title":"携手 DeepSeek，数智武大：数智教育实践创新平台重磅升级"},{"url":"https://www.stdaily.com/web/English/2026-08/25/content_568917.html","date":"2026-08-25","site":"Science and Technology Daily","title":"AI for Science Shifts from Efficiency Boost to Systemic Reform of Research"}],"region":"国内为主","layers":["org"],"issue_no":null,"pinned":false,"word_count":4783,"published_at":"2026-09-05T15:24:59.328+00:00","body_md":"## 一、AI4S 的第一道坎不是技术，是组织架构\n\nAI for Science 天然是跨学科的：需要 AI 算法人、领域科学家、工程实现与实验平台同时在场。传统以院系为单位的组织架构很难承接——课题归属、成果署名、经费分配、人员考核，每一项都在阻碍交叉。\n\n因此国内头部高校的第一步几乎都是**成立实体化机构**。这不是挂牌子，而是对组织资源、管理模式与发展战略的系统性重构：给研究人员稳定的资源倾斜、专用的科研平台和长效的考核激励机制，从根上解决跨学科合作里\"组织归属不清、资源协调困难\"的问题。\n\n鄂维南院士的判断可以作为这段变化的注脚：\"AI for Science 是交叉科学发展的新动力。\"\n\n## 二、四种建制模式\n\n### 模式一：独立学院（北京大学科学智能学院）\n\n北京大学在深圳研究生院成立了独立的**科学智能学院（School of AI for Science）**，不只是研究中心，而是集人才培养、科学研究于一体的完整建制。学院明确要在人工智能与基础科学的交叉领域开展跨学科研究，整合了信息工程学院、化学生物学与生物技术学院等多学科力量。\n\n配套的人才机制是 **\"AI+Science\" 双导师制**：学生同时由 AI 领域和科学领域的导师共同指导，确保课题既有前沿算法创新，又能精准对接真实科学问题。\n\n北大深研院还把建制延伸到了平台层：与百度智能云共建的 AI4S LAB（全球首个数智化生命科学研究平台，2025 年 9 月体验版上线）整合\"算力—模型—数据—实验\"四大要素，自研 AI4S 原生多智能体系统 BIOMA，配备超 15 个专业数据集与 22 台套高通量、自动化、自迭代智能实验设备，目标是探索具备\"逆向设计、自主发现能力\"的数智化科研平台，服务 AI4S、AI、Science 等不同角色的用户，加速\"想法—设计—执行—分析—优化\"的迭代周期。\n\n### 模式二：研究院 + 平台运营（复旦大学人工智能创新与产业研究院）\n\n复旦 AI3 研究院成立于 2021 年 11 月，以\"原创科技 + 应用转化\"为核心，聚焦 AI for Science 与人工智能技术创新，服务生命健康和经济发展重大战略需求。它的一个关键特征是**承担了复旦科研智算平台 CFFF 的建设与运行任务**——研究机构直接运营基础设施，而不是把平台交给信息中心代管。\n\n同时，AI3 与上智院通过\"1+1\"联动机制共同推动 AI 驱动科学突破，其副院长同时担任上智院的科研副院长，形成人员层面的咬合。双方在合作中遵循\"问题共定义、路径共探索、成果共创造\"原则，已支撑建设 18 个科学智能交叉学科中心，并成立\"感染性疾病数字医疗校企联合研究中心\"\"人工智能大模型校企联合研究中心\"\"云上智算校企联合实验室\"等多个校企联合实验室。\n\n成果侧的公开记录包括：伏羲气象大模型获国际基础科学大会 2025 年度科学前沿奖；女娲生命大模型构建全球首个百亿级参数 RNA 基础模型；燧人物质大模型相关成果当选《自然·机器智能》（Nature Machine Intelligence）封面论文。\n\n### 模式三：圈层式协同创新中心（浙江大学）\n\n浙江大学建立\"人工智能省部共建协同创新中心\"，以计算机学院为核心，协同之江实验室及产业龙头企业，形成\"核心层—紧密协同层—外围协同层\"的圈层式创新平台，重点在人工智能基础理论、关键技术应用等方向开展研究，为 AI4S 提供技术底座与产业转化渠道。\n\n浙大在基础设施上的另一手是\"校企合营\"：与中国移动共建全国首个校企合营模式算力中心\"启真算力中心\"，建成后 AI 算力达 711Pflops，后续接入中国移动\"百川\"算力并网平台实现统一调度。校内则推行\"众筹式\"智算平台建设思路，引导各院系、团队共同投入形成合力。\n\n### 模式四：学科交叉中心与联盟（清华、上智院、国际科学智能联盟）\n\n清华大学在姚期智院士领导的人工智能学院中明确设立 **\"AI+Science\" 研究方向**，并鼓励物理、化学等不同背景的学生申请，从源头促进学科交叉。\n\n上海科学智能研究院（2023 年 9 月成立，依托复旦大学、业务主管单位为上海市科委）走的是\"开放协作、科学家为中心\"的路线：组建百余人复合型队伍（部分来自海外院校与知名 AI 实验室，部分来自具工程经验的企业），实行企业化 OKR 管理，目标是 2030 年建成具有国际影响力的科学智能机构；2025 年 9 月参与发起科学智能战略科技力量联盟。\n\n2025 年 5 月，**国际科学智能联盟**在北京宣布成立（北大深圳研究生院等为重要参与方），目标是构建\"基础工具链—共性技术平台—场景化应用\"的全链条技术生态，推出智能化科研工具与开放平台，并推动高校构建\"AI+Science\"交叉学科课程体系、通过产学研协同破解行业底层难题。这标志着生态构建从单点项目合作走向体系化共建。\n\n## 三、人才培养：从\"加几门课\"到\"重构知识图谱\"\n\n2026 年 4 月，教育部等五部门联合印发《\"人工智能+\"行动计划》，是我国首次以跨部门联合发文形式系统谋划人工智能与教育深度融合的顶层设计。文件提出\"坚持育人为本、素养为先\"，以\"培养胜任智能时代的能力\"为核心目标——关键词不是\"掌握\"而是\"胜任\"，不是\"技能\"而是\"素养\"，折射出人才观从\"知识导向\"向\"能力导向\"的转型；并提出\"培养复合型交叉人才\"\"指导高校开设人工智能交叉融合课程，丰富跨学科、跨专业课程群\"\"推动人工智能成为高校公共基础课\"。\n\n复旦校长金力院士的解读与校内实践很有代表性：\n\n- **培养目标**：不是教会学生使用 AI，而是培养能提出好问题、能跨界创造、能持续进化的人，即**\"干细胞式\"人才**——干细胞的特点是多向分化潜力与持续自我更新能力，不预先被定义为某种特定细胞。对应到人才，真正有\"保质期\"的核心素养是三种能力：在未知领域快速建立认知框架的能力、跨越学科边界整合资源的能力、面对失败持续迭代的韧性。\n- **课程体系**：基于全校\"普及圈\"\"核心圈\"\"进阶圈\"的需求，本研一体化打造进阶式 **AI-BEST 课程体系**——B（通识基础）、E（专业核心）、S（学科进阶）、T（垂域应用）四层逐级深入，已开设逾百门课程、累计 1.3 万余人次修读。\n- **核心理念**：\"AI 不是加进课程里的味精，而是菜里的主料。\"典型例子是计算与智能创新学院与文物与博物馆学系合开的 **\"AI 考古\"课**：学生深度参与文物修复和考古数据库搭建，AI 是课程的灵魂——把 AI 拿掉，课就不存在了。\n\n其他高校的实践补充了不同层次：\n\n- **南京大学**：2024 年面向全体本科新生开设\"人工智能通识核心课程体系\"，目标是让所有专业学生都理解 AI 的基本原理与应用潜力，为将来在各自领域应用 AI 打底。这是最典型的\"普及圈\"动作。\n- **上海大学张统一院士团队**：在国内最早推动\"材料信息学\"交叉学科建设，先后设立国内第一个材料基因理念的本科专业（2016 年）和\"材料信息学\"交叉学科博士点（2023 年），构建了覆盖本、硕、博的完整培养链条，为 AI for Materials 持续输送专业人才。这是**单一学科全链条建制**的样板。\n- **武汉大学**：数智教育实践创新平台（深势科技定制，2024 年 9 月上线，2025 年 2 月接入 DeepSeek）已上线超 40 门课程、发布 2000 余篇 AI Note、服务超 4000 名师生，定位为全学科 AI 教学实训基地，落实\"五位一体\"\"四真计算\"\"三教融合\"理念。配套 AI Note 交互式学习与 AI 助教\"珞珞\"（动态学习画像 + 个性化问答）。\n- **清华大学**：Global Research Program 2026 采用\"实验室沉浸 + 教师指导 + 全校平台\"模式，前沿主题包含 AI for Science and Intelligent Computing，把校级平台向国际学生开放。\n\n## 四、产学研协同的三种模式\n\n1. **需求导入型**：以联合实验室为载体，把产业界的真实数据与应用需求导入高校。浙江大学管理学院与饿了么于 2024 年 10 月共建\"新型消费与营销智能实验室\"，把 AI 应用从理工科延伸到社会科学——对高校解决了社科研究中高质量大规模行为数据获取难的问题，对企业则获得理论支持。武汉理工大学材料科学与工程学院与腾讯云于 2026 年 8 月围绕 AI for Science、AI 赋能教育教学、智慧办公及科研算力开展交流，约定建立常态化沟通对接机制，聚焦具体科研问题与实际应用场景。\n2. **任务攻关型**：面向国家重大战略，由高校、企业、国家机构组建\"联合舰队\"。上海人工智能实验室与中国商飞上海飞机设计研究院联合推出全球首个翼型 AI 生成式系统**\"书生·翼飞\"**，按给定性能要求快速生成满足约束的翼型方案，极大缩短设计周期；气象大模型\"伏羲\"由复旦、上智院、中国气象局联合研发，\"风乌\"由上海 AI 实验室联合中国科学技术大学、上海交通大学、南京信息工程大学、中科院大气物理研究所及上海中心气象台共同发布。\n3. **生态共建型**：通过开放联盟与平台构建共享工具链和课程体系，降低创新门槛。国际科学智能联盟、星河启智开放平台（400 余家机构、120 多个实验团队入驻）、Intern-Discovery（50 家机构数据集 + 200 余专业智能体 + 低代码编排）都属于这一类。\n\n生物医药领域还有一个来自产业端的观察：企业坦言自身缺乏跨学科复合型人才，希望通过校企合作把市场化应用场景导入学校，共同培养符合产业需求的\"AI + 医药\"人才。**产学研合作的核心驱动力之一，是解决产业界的人才痛点。**\n\n## 五、组织层面的三个真问题\n\n**1. 复合型人才缺口巨大。** AI4S 需要既精通 AI 算法、又深刻理解特定科学领域核心问题的顶尖人才，全球范围内都极为稀缺。高校虽已布局 AI+X，但人才成长有周期，短期供需矛盾突出。\n\n**2. 评价体系的惯性。** 传统院系设置与以学科为基础的学术评价体系，天然不利于跨学科团队成长：一个成果算计算机系还是物理系？如何评价在交叉领域做出贡献的学者？高校内部各学科人才培养体系相对独立，跨学科交叉融合率低、存在技术壁垒。北大科学智能学院这类实体建制的真正价值，正是在考核与归属上开了特区。\n\n**3. 从\"AI for Science\"到\"AI as Scientist\"的角色演进。** 目前 AI 多扮演\"辅助工具\"，未来趋势是演变为\"科研合作者\"（Collaborator）乃至\"自主发现者\"（Scientist）。已有研究开始探索由多个不同专业角色的 AI 智能体组成\"虚拟科研团队\"共同解决复杂科学问题。要让这一步走稳，前提是建立**可信 AI 体系**：发展动态纠错机制、构建科学事实锚点、提升模型可解释性——只有当科学家能理解 AI 为何做出某个预测、并能验证其推理过程时，AI4S 才能从高效工具变成值得信赖的科研伙伴。\n\n上海交大团队提出的\"智能化科学设施\"（AISF）构想给出了一个架构蓝图：整合算力支撑、科学引擎（科学大模型 + 数据）与无人实验三大模块，并建立可信协同与专家反馈机制。\n\n## 六、给高校管理层的清单\n\n1. **建制先行**：设独立学院/研究院并赋予考核特区权限，优先于设虚拟交叉平台。\n2. **平台归属研究机构而非纯运维部门**：复旦 AI3 运营 CFFF 的模式能保证平台跟着科研任务演进。\n3. **人员咬合**：像复旦—上智院那样让副院长双向兼职，比签战略协议有效。\n4. **课程分三圈**：普及圈（通识必修，学南大）、核心圈（专业核心，AI-BEST 的 E/S 层）、进阶圈（垂域应用与实战，T 层 + 实训基地）。\n5. **把 AI 做成\"主料\"**：判断课程是否真交叉的标准是——拿掉 AI，这门课还成立吗？\n6. **本硕博全链条**：在优势学科（如材料信息学）先跑通一条完整链条，比在所有学科铺开更容易出成果。\n7. **协同选模式**：有数据需求走\"需求导入型\"，有国家任务走\"任务攻关型\"，有生态野心走\"生态共建型\"，不要三种同时上。\n"},"report-overseas":{"id":4,"slug":"report-overseas","title":"海外坐标：从 NAIRR 国家资源到校级 AI Catalyst","kind":"report","dek":"NSF 的三步走——NAIRR 试点、3500 万美元建运营中心、州与区域 AI 基础设施 Hub，加上 8300 万美元的科学数据基建；校级层面则是斯坦福 UIT 的 AI Catalyst 咨询模式与剑桥 Accelerate 的跨校学术网络。附中美路径对照表。","tags":["NAIRR","NAIRR-OC","NSF AI Infrastructure Hubs","AI Catalyst","剑桥 Accelerate","Applied AI for Science"],"sources":[{"url":"https://www.nsf.gov/geo/updates/national-artificial-intelligence-research-resource-nairr","date":"2024-03-08","site":"NSF","title":"National Artificial Intelligence Research Resource (NAIRR) Pilot"},{"url":"http://ecas.cas.cn/xxkw/kbcd/201115_148189/ml/xxhzlyzc/202509/t20250925_5083947.html","date":"2025-09-25","site":"中国科学院网信工作网","title":"美 NSF 拟建立国家 AI 研究资源运营中心"},{"url":"https://www.bu.edu/research/2025-10-08/nsf-artificial-intelligence-research-resource-the-nairr-operations-center-nairr-oc-2026/","date":"2025-10-08","site":"Boston University Research","title":"NSF Artificial Intelligence Research Resource: the NAIRR Operations Center (NAIRR-OC) 2026"},{"url":"https://stem.zjnu.edu.cn/2026/0815/c9134a580020/page.htm","date":"2026-08-14","site":"浙江师范大学","title":"美国 NSF 和区域 AI 基础设施中心将推动全国范围内人工智能科学研究发展"},{"url":"https://ecas.cas.cn/xxkw/kbcd/201115_149991/ml/xxhjsyjcss/202608/t20260819_5118602.html","date":"2026-08-19","site":"中国科学院网信工作网","title":"美 NSF 投入 8300 万美元打造科学数据基础设施"},{"url":"https://uit.stanford.edu/service/ai-catalyst","date":"2026-09-03","site":"Stanford UIT","title":"AI Catalyst | Stanford University IT"},{"url":"https://science.ai.cam.ac.uk/events/ai-for-science-summit-2026.html","date":"2026-08-31","site":"University of Cambridge","title":"AI for Science Summit 2026 | Accelerate Programme"},{"url":"https://carcc.org/2026-08-27/all-things-ai-september-2026/","date":"2026-08-27","site":"CaRCC","title":"All Things AI – September 2026"},{"url":"http://m.toutiao.com/group/7657441769625223721/","date":"2026-07-01","site":"NVIDIA 英伟达博客","title":"NVIDIA AI 基础设施赋能 NAIRR 科学计划"},{"url":"https://www.publicnow.com/view/C5BB2C87FF4EF3FEF388835440ECD166B8C4CB2F","date":"2026-08-21","site":"PublicNow / NUS","title":"Singapore launches eight inaugural AI4S projects"},{"url":"https://www.hanlin.com/archives/1294042","date":"2026-08-11","site":"翰林国际教育 / 5W AI","title":"全球首份“50 所大学 AI 产出能力报告”发布"},{"url":"https://liuxue.xdf.cn/blog/blog_8051973.shtml","date":"2026-09-02","site":"新东方前途出国","title":"2026 美国顶尖大学 AI 硕士项目集中上线"},{"url":"https://www.tsinghua.edu.cn/gjhz/info/1202/2704.htm","date":"2026-09-05","site":"清华大学国际合作与交流处","title":"2026 Tsinghua University Global Research Program"},{"url":"https://arxiv.org/abs/2608.26519","date":"2026-08-27","site":"arXiv","title":"Report of the 2026 Workshop on Next-Generation Ecosystems for Scientific Computing"},{"url":"https://www.stdaily.com/web/English/2026-08/25/content_568917.html","date":"2026-08-25","site":"Science and Technology Daily","title":"AI for Science Shifts from Efficiency Boost to Systemic Reform of Research"}],"region":"海外","layers":["region","org"],"issue_no":null,"pinned":false,"word_count":5826,"published_at":"2026-09-05T15:24:58.878+00:00","body_md":"## 一、美国：把 AI4S 基建做成\"国家资源\"\n\n国内高校的算力平台多是校级项目，美国的路径是把 AI 科研资源上升为**国家级基础设施**，再由高校按需接入。理解这条主线，才能读懂海外高校在做什么。\n\n### NAIRR：从试点到运营中心\n\nNSF 主导的\"国家人工智能研究资源\"（NAIRR，National Artificial Intelligence Research Resource）于 2024 年 1 月以试点形式启动，由 NSF 联合 10 个其他联邦机构与 25 家非政府伙伴，向全美研究与教育社区开放政府资助的、以及产业与其他方贡献的**计算资源、数据集、AI 模型与培训工具**。\n\n试点的成绩单：已支持全美 48 个州超过 400 个研究团队，在农业、药物研发、网络安全、教育等领域取得突破（另有厂商口径称两年间推动了 700 多个项目的创新研究，涵盖蛋白质预测与传染病管理）。\n\n2025 年 9 月 3 日，NSF 宣布投资 3500 万美元建立\"国家 AI 研究资源运营中心\"（NAIRR-OC），把 NAIRR 从试点过渡到可持续、可协调的国家计划。NAIRR-OC 被定位为\"社区主导型\"运营中心，承担三项任务：\n\n1. **组织与领导**：制定整体运营框架与管理结构，建立与联邦机构、私营伙伴的协同机制，设立衡量成效的关键指标；\n2. **能力建设与社区扩展**：开发统一的 NAIRR 门户网站集成各类 AI 资源，整合数据、模型与工具支持研究与教学，开展社区推广与用户需求调研；\n3. **对接现有资源**：与 NAIRR 试点团队协调并逐步接管其功能，规划未来资源分配与用户支持机制。\n\n对高校的直接影响：波士顿大学等校已开始在校内征集教师，牵头或参与机构层面的 NAIRR-OC 提案——**国家基建的运营权本身，正在成为研究型大学的竞争标的。**\n\n### 州与区域 Hub：把算力下沉到普通高校\n\n2026 年 8 月 4 日，NSF 正式启动\"国家和区域人工智能基础设施中心\"（State & Regional AI Infrastructure Hubs）项目，目标是扩大 AI 驱动科学发现所需算力资源的可及性，并强化高校的研究、教育与劳动力培养。项目要求各中心与 NAIRR 等国家层面计划对接，实现资源共享与协同，形成全国性 AI 科研基础设施网络。该计划的公开材料把**师资培训放在核心位置**。\n\n配套动作还有 CaRCC（Campus Research Computing Consortium，校园科研计算联盟）的月度汇编 \"All Things AI\"，集中发布 NAIRR 试点与其他 AI 计划的机会、活动与培训；2026 年 9 月刊里列出了 Gateways 2026（9 月 9—11 日，华盛顿特区，科学网关与科研基础设施社区年会）以及 NSF State & Regional AI Infrastructure Hubs 网络研讨会第二场（9 月 2 日）。**一个成熟的生态里，\"信息聚合 + 培训 + 年会\"这三件小事是高校信息化同行最直接的连接方式。**\n\n### IDSS：8300 万美元砸向科学数据基础设施\n\n2026 年 7 月 22 日，NSF 通过\"综合数据系统与服务\"（IDSS）提供总计 8300 万美元资助，六个方向分别由莫格里奇研究所（FabAID，连接数据仓库/算力/科研网络并与 NAIRR 对接）、加州大学圣地亚哥分校（NDP 国家数据平台）、加州大学洛杉矶分校（iDLab 交互式发现实验室）、加州大学欧文分校（BRIDGE 国家中心）、田纳西大学诺克斯维尔分校（NSDF 国家科学数据基础架构）、亚利桑那大学（MESA 多学科科研推进环境）牵头。\n\n值得注意的是牵头机构的分布：不全是顶尖私立名校，UCSD、UCLA、UCI、UTK、Arizona 这些公立大学承担了大部分国家级数据基础设施。**\"基建由公立大学承建，科研由全体高校共享\"**，是美国这套体系的分工逻辑。\n\n### 算力供给侧：NVIDIA 的 NAIRR 专属资源\n\nNVIDIA 通过基于云端的资源为 NAIRR 试点项目提供支持，向研究人员提供**至少一个月、最低配置为 4 个 NVIDIA DGX 节点的专属访问权限**，并在整个项目期间提供接入指导。三个已披露的高校案例：\n\n- **Polymathic AI 联盟**（熨斗研究所、剑桥大学、劳伦斯伯克利国家实验室）：用\"Well\"大规模数据集训练迄今规模最大、适用性最广的类流体行为基础模型；\n- **密歇根大学**航空航天工程系 Venkat Viswanathan 团队：开发把领域分子 AI 与通用 LLM 结合的模型融合框架，分子基础模型系列 MIST（Molecular Insight SMILES Transformers）基于 NAIRR 提供的 40 GPU DGX 集群，以及 ALCF Polaris 集群上额外分配的 20 万 NVIDIA GPU 小时完成开发，并用 NGC PyTorch 容器保证跨集群可复现的 GPU 加速开发；\n- **波士顿大学** Hariri 计算研究所与新兴传染病中心：用传染病与重点病原体文献语料训练 LLM，支撑名为 BEACON 的疫情监测计划，为现场专家与疫情分析师提供决策支持。\n\n## 二、校级实践：斯坦福 AI Catalyst 与剑桥 Accelerate\n\n### 斯坦福：把 IT 部门变成\"科研 AI 咨询团队\"\n\n斯坦福大学 IT（UIT）的 **AI Catalyst** 是目前公开信息里最贴近\"高校信息中心怎么支持 AI\"的样本。它由 2024 年启动的 AI Playground 演进而来——Playground 已被证明是探索新 AI 工具并与校内系统集成的沃土，大量需求通过 `#ai-playground` Slack 频道涌入；AI Catalyst 则在此基础上提供**结构化路径与咨询**。\n\n服务清单很具体：\n- 就 AI 使用的最佳实践与透明度提供建议；\n- 审计当前 AI 使用情况、评估需求，制定定制化的 AI 采纳战略规划；\n- 为教师、研究者、学生搭建 AI 解决方案或系统，解决其具体需求（例如分析大规模数据集）；\n- 基于 UIT 企业级 AI 能力构建定制的 AI 方案。\n\n目前团队支持的大型项目伙伴包括财务管理服务处（FMS）、对外关系与斯坦福校友会、法学院、科研管理办公室（ORA）。UIT 还明确说明\"FY26 项目容量已满\"，但仍愿意先做需求评估。**一个校级 AI 支持团队会因为需求过多而排满年度产能**——这本身就是 AI4S 已进入常态化的最好证据。\n\n另一个值得注意的细节：AI Catalyst 的第一项服务不是搭平台，而是\"AI 使用的最佳实践与透明度咨询\"。高校 IT 组织在 AI4S 中的角色，正在从\"提供机器\"转向\"提供规范、审计与方法\"。\n\n### 剑桥：Accelerate Programme 与年度 AI for Science Summit\n\n剑桥大学的 **Accelerate Programme for Scientific Discovery** 走的是学术共同体路线。2026 年的 AI for Science Summit 定于 11 月 24 日在丘吉尔学院举办，把 AI for Science 社区聚到一起，合并各自的洞见与经验，推动一个有影响力的研究议程。\n\n已确认的讲者与讨论嘉宾包括：Hana Aliee（Cancer Research UK 剑桥研究所）、Boris Bolliet（剑桥）、Sadiq Jaffer（剑桥）、Neil Lawrence（剑桥）、Cait Newport（牛津）、Stephen Roberts（牛津）、Richard Turner（剑桥）、Max Welling（阿姆斯特丹大学）。跨机构（剑桥—牛津—CRUK—阿姆斯特丹）的配置，说明英国 AI4S 是以**跨校学术网络**而非单一平台的形式组织的。\n\n学术工程侧，剑桥的 Tobias Grosser 团队在 MLIR 生态里做 HPC 与 AI 的多级编译器设计（MLIR GPU dialect 用于科学计算、MLIR 的一等 MPI 支持、面向 Cerebras Wafer-Scale Engine 的编译目标），2026 年 5 月还在台大做了公开报告。编译器与算子层是\"国产/多元芯片适配\"成本高的根源，海外高校在这个层次上的开源投入值得追踪。\n\n### 新加坡：国家计划 + 高校学科优势\n\n新加坡于 2026 年 6 月 16 日正式启动 AI4S 国家计划下的首批 8 个项目。在 2026 QS 数据科学与人工智能学科排名中，新加坡国立大学（NUS）与南洋理工大学（NTU）分列全球第 3、第 4，其中 NUS 被点名\"在 AI for Science 方向取得突破性进展，论文引用率全球前三\"。**国家计划 + 学科排名优势**的组合，是小型经济体做 AI4S 的典型路径。\n\n## 三、评价与人才培养：新的坐标系\n\n### 5W AI 高等教育指数 2026\n\n5W AI Communications 发布的《5W AI高等教育指数2026》是全球首个专门衡量大学 AI 产出能力的基准报告，覆盖 13 个国家和地区的 50 所大学。斯坦福、MIT、CMU 位列前三；MIT 的 CSAIL（计算机科学与人工智能实验室）被称为按师资数量计算全球最大的 AI 研究机构。第二梯队（综合得分 70—77.9）包括苏黎世联邦理工（77.5）、牛津（75.0）、剑桥（74.5）、华盛顿大学（74.0）、伊利诺伊大学厄巴纳-香槟分校（72.5）、康奈尔（71.5）、佐治亚理工等。\n\n对国内高校的参考价值在于：这套指数衡量的是**AI 产出能力**而非传统学术声誉，是与 QS 学科排名不同的另一把尺子。\n\n### AI 硕士项目的集中上线\n\n2025—2026 年，美国多所顶尖大学密集推出独立的 AI 硕士项目：加州大学伯克利分校 MAIML（人工智能与机器学习硕士，由 CDSS 与 EECS 联合设计）、芝加哥大学 MS-AAI（应用人工智能硕士）、圣路易斯华盛顿大学 AI Engineering MEng、**加州大学尔湾分校 Applied AI for Science（聚焦 AI 在科学研究中的前沿应用）**、密歇根大学 AI Engineering MEng。\n\nUCI 直接把 \"Applied AI for Science\" 作为学位名，是国内\"AI+X\"交叉培养的一个海外镜像。共同特征是从\"散落在计算机、数据科学、统计院系里的课程\"转向**独立设置的学位项目**，录取标准对标金融工程/金融数学，竞争激烈。\n\n### 科研训练项目把 AI4S 写进主题\n\n清华大学的 Global Research Program 2026（面向大陆以外顶尖高校本科生与研究生的 6 周以上沉浸式科研体验）采用\"实验室沉浸 + 教师指导 + 全校平台\"模式，其前沿主题明确包含 **AI for Science and Intelligent Computing**、碳中和与能源系统转型、智能制造等。这类项目的意义是把校级平台向国际学生开放，既是人才培养，也是平台的国际能见度。\n\n## 四、中美路径对照\n\n| 维度 | 国内高校 | 海外（以美国为主） |\n|---|---|---|\n| 基础设施归属 | 校级平台为主，省市级公共设施刚起步（江苏 AI4S 公共算力中心） | 国家级资源（NAIRR、IDSS、State & Regional Hubs），高校按需接入 |\n| 建设资金来源 | 学校专项、校企合营（浙大—中国移动）、地方财政 | 联邦资助（NSF）、厂商贡献（NVIDIA DGX 专属资源）、慈善与产业伙伴 |\n| 运营主体 | 研究院/信息中心（复旦 AI3 运营 CFFF、上大信息化团队） | 社区主导运营中心（NAIRR-OC）、大学 IT 咨询团队（斯坦福 AI Catalyst） |\n| 分配方式 | 排队为主（近七成），券/配额兴起（清华 easycompute） | 申请制 allocation（NAIRR 分配轮次、ALCF Polaris GPU 小时） |\n| 数据供给 | 自建语料库与数据平台（复旦 260+ 学科数据、上智院三大领域） | 国家级数据基础设施 + 国际权威库（EBI、ECMWF 经 Intern-Discovery 引入国内） |\n| 人才培养 | AI+X 交叉学院、双导师制、通识课（北大科学智能学院、南大 AI 通识、复旦 AI-BEST） | 独立 AI 硕士学位（UCI Applied AI for Science、Berkeley MAIML）、师资培训纳入国家计划 |\n| IT 部门角色 | 建平台、发额度、运维 | 提供咨询、审计、最佳实践与透明度规范（斯坦福 AI Catalyst） |\n\n一句话概括差异：**国内是\"高校自己建\"，海外是\"国家建好、高校接入 + IT 部门做咨询\"。** 两者并不是谁更先进，而是财政结构与科研组织方式不同。但对国内高校信息中心而言，有两点可以直接借鉴：\n\n1. **把 IT 组织的能力从运维扩展到咨询。** 斯坦福 AI Catalyst 的四项服务里，\"AI 使用最佳实践与透明度\"\"现状审计与战略规划\"是纯知识服务，不需要新硬件投入，却是院系最容易缺的部分。\n2. **主动对接公共基础设施，而不是凡事自建。** NAIRR 的价值在于让普通高校也能拿到 DGX 级专属资源；江苏省级 AI4S 公共算力中心提供 700P 算力与 70 余款模型 API，省属院校的最优解很可能是\"接入 + 补特色数据\"。\n\n## 五、值得持续追踪的信号\n\n- NAIRR-OC 最终花落谁家，以及统一门户上线后的资源目录与申请流程；\n- NSF State & Regional AI Infrastructure Hubs 的中标机构名单（尤其是有多少非顶尖研究型大学入选）；\n- 剑桥 AI for Science Summit 2026（11 月 24 日）发布的研究议程；\n- arXiv 上的科学计算生态报告：《Report of the 2026 Workshop on Next-Generation Ecosystems for Scientific Computing: Harnessing Community, Software, and AI for Cross-Disciplinary Team Science》（2608.26519）系统讨论了社区、软件与 AI 在跨学科团队科学中的作用，署名作者覆盖美国国家实验室与高校的大量科研软件负责人；\n- 鄂维南院士在 2026 AI for Science Congress 上的判断：AI4S 已进入\"下半场\"，从构建 AI 科研工具转向**重构整个科研生态**——\"AI 的价值远不止加速研究，它将结构性地重塑基础研究的生产模式与运行体系\"，下一阶段的关键问题是\"AI for Science 之后\"：当技术能力跃升，科研的组织方式、评价标准与资源配置该如何系统性重新设计。他设想的是一个整合算力、仿真引擎、领域知识库与自动化实验室的**开放、通用科研基础设施**。\n\n这最后一条，恰好是国内高校信息中心下一阶段要回答的问题。\n"},"report-research-agent":{"id":25,"slug":"report-research-agent","title":"科研智能体进高校：谁能跑通“假设—实验—论文”的全流程编排","kind":"report","dek":"复旦“大圣”以300余个技能包跑通假设—实验—验证闭环，上交大SciMaster六小时比肩资深博士一到三个月工作量，Google Co-Scientist首次在真实实验室一次长出三种单层半导体，国家超算互联网上线400余个科学计算智能体。","tags":["科研智能体","多智能体编排","AI4S","星河启智","SciMaster","Co-Scientist","MCP","智能体评测"],"sources":[{"url":"https://m.jfdaily.com/wx/detail.do?id=1076567","date":"2026-03-05","site":"上观新闻","title":"中国高校加速布局AI for Science，科研智能体引领科研范式变革"},{"url":"https://news.fudan.edu.cn/2026/0414/c3521a148731/page.htm","date":"2026-04-14","site":"复旦大学","title":"科研合伙人“大圣”来也"},{"url":"https://ecas.cas.cn/xxkw/kbcd/201115_149501/ml/xxhcxyyyal/202603/t20260306_5103462.html","date":"2026-03-06","site":"中国科学院网信工作网","title":"我国发布超级科研合伙人“大圣”"},{"url":"https://news.sjtu.edu.cn/mtjj/20260203/219648.html","date":"2026-02-02","site":"上海交通大学新闻学术网","title":"人工智能赋能基础科学 上海交大发布科学基座模型与科研智能体等重磅成果"},{"url":"https://www.sohu.com/a/981593011_120988576","date":"2026-01-30","site":"搜狐网/上证报","title":"上海交大发布通用科研智能体SciMaster与基座模型Innovator"},{"url":"https://finance.sina.com.cn/tech/roll/2026-09-15/doc-inirxhzw3652035.shtml","date":"2026-09-15","site":"新浪科技","title":"零门槛搭建科学计算智能体，国家超算互联网亮相2026算力网发展大会"},{"url":"https://hub.baai.ac.cn/view/57610","date":"2026-09-01","site":"智源社区","title":"Co-Scientist升级：AI走出屏幕，首次在真实实验室「造出」半导体"},{"url":"https://www.mse.tsinghua.edu.cn/info/1063/3854.htm","date":"2026-08-30","site":"清华大学材料学院","title":"清华大学材料科学与工程研究院《材料科学论坛》学术报告：Science Navigator：新一代科研知识库与智能体平台"},{"url":"https://www.sznews.com/news/content/2026-09/11/content_32169598.htm","date":"2026-09-11","site":"深圳新闻网","title":"让AI能“想”会“做”，深圳科研团队提出轻量化“双模型协作”材料创制智能体“材智云脑MatBrain”"},{"url":"http://ecas.cas.cn/xxkw/kbcd/201115_146615/ml/xxhcxyyyal/202501/t20250117_5045346.html","date":"2025-01-17","site":"中国科学院网信工作网","title":"美研究人员推出代理实验室 加速科学发现进程"},{"url":"https://news.sina.cn/ai/2024-11-26/detail-incxkxsh7377908.d.html","date":"2024-11-26","site":"新浪新闻","title":"超越 GPT-4o：开源科研模型 OpenScholar 登场，4500 万篇论文检索增强生成回答"},{"url":"https://t.cj.sina.com.cn/articles/view/6456450127/180d59c4f00102cz06","date":"2026-09-14","site":"新浪财经/人民网","title":"服务长周期科研任务 开源基础大模型“书生-S2”发布"},{"url":"https://cernet.edu.cn/xxh/focus/li_lun_yj/202512/t20251204_2705787.shtml","date":"2025-12-04","site":"中国教育和科研计算机网CERNET","title":"主任谈丨如何建设高校智能体？"},{"url":"https://www.caigou.com.cn/news/2026051516.shtml","date":"2026-05-15","site":"教育装备采购网","title":"上海交大“致远一号”赋能智能体模式 引领高校智能体规模化应用"},{"url":"https://export.shobserver.com/baijiahao/html/953371.html","date":"2025-07-26","site":"上观新闻","title":"从科研智能体到罕见病诊断,上海交大最新发布五项全球领先AI成果"}],"region":"国内外","layers":["tools","model","org"],"issue_no":null,"pinned":false,"word_count":7092,"published_at":"2026-09-16T00:05:02.869+00:00","body_md":"# 科研智能体进高校：谁能跑通\"假设—实验—论文\"的全流程编排\n\n## 一、这一年发生了什么：从文献问答到全流程编排\n\n\"智能体\"与\"大模型\"的区别，在一个科研场景里看得最清楚：大模型能回答\"分子动力学在药物筛选中的典型流程是什么\"，智能体则要自己检索文献、调用计算软件、设计实验、分析结果、写出报告——全程只需要研究者给一个自然语言方向。2024 年以来，这条从\"问答\"到\"编排\"的演进明显提速，而 2025—2026 年国内高校和科研院所开始成建制地进场。\n\n时间线上的几个节点值得记录。**2024 年 8 月**，Transformer 论文作者之一 Llion Jones 创立的 **Sakana AI** 推出 **AI Scientist**，首次把\"提出假设—设计实验—运行实验—写论文—自我评审\"串成流水线；其 **AI Scientist-v2** 生成的论文成为首篇完全由 AI 自主完成并通过同行评审的研讨会论文，被 **ICLR 2025** workshop 收录。**2025 年 1 月 8 日**，**AMD** 与**约翰斯·霍普金斯大学**发布 **Agent Laboratory** 框架，用 PhD、Postdoc、ML 工程师、Professor 四个代理分工完成文献综述、实验设计、代码实现与论文评审，官方报告研究成本下降 **84%**，其中 o1-preview 作为后端产出最佳。**2025 年**，**斯坦福大学** James Zou 团队与 **Chan Zuckerberg Biohub** 的\"虚拟实验室\"（Virtual Lab）登上《自然》：由 PI 智能体、免疫学家与计算生物学家等专家智能体和科学评论员智能体组成的团队，自主设计出 SARS-CoV-2 纳米抗体并经实验表征验证——这为\"跨学科协作稀缺\"的普通课题组提供了一个可复用的组织模板。\n\n2026 年，重心移到国内与真实实验室。**3 月 1 日**，**上海科学智能研究院（上智院）**联合**复旦大学**发布升级版星河启智平台及超级科研合伙人\"大圣\"；**3 月 4 日**，**香港科技大学**主办\"AI for Discovery\"峰会，会上披露了港科大\"AI for Lab\"计划与实验室智能体 AINA。**9 月**，**国家超算互联网**在算力网发展大会上披露其科学计算智能体生态的最新规模，**上海人工智能实验室**发布强化长程科研与智能体能力的\"书生-S2\"，**中国科学院深圳先进技术研究院**在《自然-机器智能》发表轻量化双模型科研智能体 MatBrain。科研智能体从论文里的概念，变成了有平台、有技能库、有评测、有运营模式的基础设施。\n\n## 二、国内样本：四种可辨识的落地路线\n\n### 复旦—上智院：星河启智与\"大圣\"，技能包加群体记忆\n\n2026 年 3 月 1 日，上智院联合复旦大学在徐汇\"模速空间\"发布全面升级的**星河启智科学智能开放平台**，核心载体是超级科研合伙人\"**大圣**\"。据复旦校报与中科院网信工作网的报道，\"大圣\"整合多模态科学大模型、**300 余个专家级科研技能模块（Skills）**与长周期多线程的群体记忆架构，通过双层沟通与分支治理机制隔离模糊指令、避免复杂任务中的路径失序；科学家用自然语言提出任务方向后，\"大圣\"做中心化决策与任务拆解，调度多智能体协同执行，并全程沉淀结构化科研记忆。\n\n效果数据来自上观新闻对 3 月 4 日港科大峰会的报道：复旦\"大圣\"在 RNA 分类与设计任务上准确率达 **96%**，在 siRNA 设计中将实验成功率提升**超 50%**，支撑了转化价值 **2000 万元**的新型补锂剂研发与潜在价值 **5 亿美元**的 FIC 类药物发现。发布会现场还演示了自然语言指令直达上智院生命实验室的实时实验：关键参数自动预填充，实验流程转化为机器可执行代码，设备远程启动。星河启智平台本身于 2025 年 7 月问世，已形成\"数据—模型—算力—实验—智能体—社区\"一体化闭环。\n\n### 上海交大：SciMaster 与基座模型 Innovator，把评测当成基础设施\n\n**上海交通大学**的路线更强调\"基座模型 + 智能体 + 评测\"三件套。2025 年 7 月 26 日世界人工智能大会期间，上交大发布科学基座大模型 **Innovator**（与**深势科技**、上海算法创新研究院联合研发）及通用科研智能体 **SciMaster**，构建\"搜、读、算、做、写\"全链条能力；2026 年 1 月 29 日，上交大人工智能学院再办\"Agentic Science at Scale\"研讨会，鄂维南院士作主旨报告，同期完成产学研战略签约，并以智能体大赛推动生态共建——赛事吸引 **44 所高校、160 余支队伍**参赛，作品覆盖文献分析、实验设计等环节。\n\nSciMaster 的两个细节对高校信息中心特别有参考价值。一是**思维链可编辑**：研究者可以随时干预智能体的任务执行逻辑，而不是等它跑完再返工；二是上交大**同步建设了智能体评测系统**，把\"科研智能体跑得好不好\"变成可量化、可对比的问题，为规模化部署提供标准化基础设施。效率口径同样来自上观新闻：SciMaster 运行 **6 小时**的成果可比肩资深理论物理学博士 **1—3 个月**的饱和工作量。\n\n### 港科大：AINA 与\"AI for Lab\"，让智能体动手\n\n港科大在 3 月 4 日峰会上披露了正在推进的\"AI for Lab\"计划，开发实验室智能体 **AINA**，方向是主动推理与自动化实验的深度融合。校长叶玉如之外的另一个案例来自郭毅可院士团队：其智能体系统**仅用两天**自动生成了\"活化污泥水处理\"的完整实验室工作流程，包括任务拆解、报告生成、授权批准、自动修改直至最终报告，实现从教授指令到成果产出的全自动运行。这条路线的关键不是模型参数，而是智能体与实验室授权、审批、设备控制这些\"脏活\"接口的打通。\n\n### 国家超算互联网：把智能体做成公共基础设施\n\n**国家超算互联网**给出了第四种路线：不自建单点智能体，而是做生态。2026 年 9 月 15 日算力网发展大会上，曙光智算总裁何牧君披露：平台注册用户超 **170 万**，汇聚超 **350 万 CPU 核心、25 万 GPU 卡**，国产算力占比 **99% 以上**；已建成材料计算、工业仿真等 **6 大智能体矩阵**，覆盖 **170 余个**核心计算场景，累计上线智能体 **400 余个**、知识库 **1000 余个**、MCP（科学计算调用协议）工具 **13000 余个**、技能 **1 万余项**。普通科研人员依托 **1.6 万余个**内容组件与对话式构建工具，无需精通编程即可\"搭积木\"式组建专属科学计算智能体。平台已与**北京大学、东南大学、华大基因**等数十家高校院所及企业合作，典型成果包括国产第一性原理软件 **ABACUS** 与 GPU 加速分子动力学工具 **SPONGE**；配套的伙伴模式提供最高 **50 万元**经费或等额算力、最高 **60%** 算力收益分成，每月举办 20 场以上 Workshop。对高校而言，这是一个可以直接\"接入而不重建\"的公共能力。\n\n### 两个轻量化信号：MatBrain 与书生-S2\n\n**中国科学院深圳先进技术研究院**喻学锋团队 2026 年 9 月 10 日在《自然-机器智能》发布的\"**材智云脑 MatBrain**\"，代表了对\"堆参数\"路线的反向思考：由 **30B** 参数的 Mat-R1（负责\"想\"——材料知识理解、科学推理、结果判断）与 **14B** 参数的 Mat-T1（负责\"做\"——调用材料数据库、结构生成模型与计算软件）组成双模型协作架构。训练侧用了约 **25.2 万条**高质量材料指令数据；工具侧建成 Mat-MCP 平台，把 Materials Project、MatterGen、Pymatgen、CHGNet、VASP 统一封装为可调用工具，并用 **2 万个**复杂材料科研问题做强化学习。结果：材料预测综合准确率较 **GPT-5、DeepSeek-R1** 等大模型提升 **66%**，硬件部署成本降低**超 95%**——智能体得以从大型计算中心走向普通实验室工作站。其电催化剂应用完成了从科学假设、**3 万个**候选结构生成、多阶段计算筛选到实验验证的完整链条，团队还在推进具身智能\"机器人科学家\" Dr. Mind。\n\n模型侧的对应信号是 **上海人工智能实验室** 2026 年 9 月 13 日在浦江创新论坛发布的\"**书生-S2**\"：重点提升长程科研能力与智能体能力，在 Biology-Instructions、Mol-Instructions 等生命科学与材料任务评测上处于开源模型第一梯队。长程任务对持续执行和上下文保持的要求，正是科研智能体区别于聊天助手的地方。\n\n## 三、海外参照：架构怎么设计，可靠性怎么兜底\n\n**Google DeepMind** 的 **AI Co-Scientist**（基于 Gemini 的多智能体科研系统）与**杜克大学**的联合升级版本，是当前\"实验室在环\"最完整的公开样本，论文编号 arXiv 2602.03837。此前版本只做\"计算内假设生成\"；升级后首次以真实实验执行为基础闭环。材料科学部分的验证全部在杜克大学王浩哲课题组完成：针对实验室自建 CVD 系统的几何结构与原料，Co-Scientist 从 **272 个**候选方案中提出以六氯乙烷替代剧毒四氯化钛作为前驱体，经 **25 轮**迭代生长出与 Ti₃C₂Tₓ MXene 晶格特征高度一致的二维层状晶体；在没有任何历史配方参考的情况下，仅凭设备硬件约束生成完整工艺参数，**第一次尝试**即合成出三角形单晶尺寸超 **50 微米**的单层 MoS₂，推广到此前从未合成过的 MoSe₂ 和 WS₂ 同样一次成功，借助 Gemini 3 Deep Think **数分钟内**生成配方并转化为设备控制指令，三种材料首次生长全程约 **一小时**。生物学部分与**哥伦比亚大学**合作，从稀疏成像数据预测工程大肠杆菌群集形态，四项形态指标中三项与未发表的湿实验测量定量吻合。\n\n对高校治理更有参考价值的是其可靠性设计：将幻觉与抄袭惩罚写入优化目标，论文中每一项定量结论与原始实验运行日志逐条比对；一项 **30 位**领域专家、共 **450 次**独立评审的双盲研究证实这些机制显著降低严重幻觉与抄袭发生率；内置安全系统拒绝了 **98.7%** 的有害研究请求。这组做法直接回应了学界对\"AI 科研编造结果\"的两大质疑，也值得写进任何校级科研智能体的验收标准。\n\n文献侧的基础设施则以 **Ai2（艾伦人工智能研究所）与华盛顿大学**的 **OpenScholar** 为代表：基于 **4500 万篇**论文构建检索增强系统，优化后的 **8B 参数**模型在专家对比中，**20 位**专家的 **500 次**实验里有 **72%** 认为 OpenScholar 的输出超过人类专家写的答案——而 GPT-4o 在同类任务中的引用捏造率高达 **78%—90%**。该项目从数据、代码到模型权重全部开源，2026 年 2 月 4 日登上《自然》。对预算有限的高校，OpenScholar 证明\"小模型 + 好语料 + 强检索\"可以支撑起可审计的引用质量。\n\n## 四、主要科研智能体与平台盘点\n\n| 系统/平台 | 开发方 | 架构与分工 | 覆盖环节 | 关键数字 |\n| --- | --- | --- | --- | --- |\n| 大圣（星河启智） | 上智院＋复旦大学 | 多模态科学大模型＋300 余个 Skills＋群体记忆，中心化决策调度多智能体 | 假设—实验—验证—迭代闭环 | RNA 分类准确率 96%；siRNA 成功率提升超 50% |\n| SciMaster / Innovator | 上海交大＋深势科技等 | 科学基座模型＋通用智能体，思维链可编辑，配套评测系统 | 搜、读、算、做、写全链条 | 6 小时约等于博士 1—3 个月工作量；大赛 44 校 160 余队 |\n| AINA / AI for Lab | 香港科技大学 | 主动推理＋实验室自动化融合 | 实验室工作流自动生成与执行 | 活化污泥水处理全流程 2 天自动完成 |\n| 超算互联网智能体生态 | 曙光智算（国家超算互联网） | 对话式构建＋1.6 万余组件＋MCP 工具 13000 余个 | 材料计算、工业仿真等 170 余个场景 | 注册用户 170 万；智能体 400 余个；伙伴最高 50 万元支持 |\n| Science Navigator | 北京科学智能研究院＋深势科技 | 2 亿篇文献＋9000 万学者知识库，多模态检索 | 学术搜索、问答、情报订阅 | 文献超 2 亿篇；实时更新＋订阅推送 |\n| Co-Scientist | Google DeepMind＋杜克大学等 | Gemini 多智能体＋实验室在环，幻觉/抄袭惩罚入目标 | 假设—真实实验—论文 | 一次长出三种单层半导体；拒绝 98.7% 有害请求 |\n| AI Scientist-v2 | Sakana AI | 智能体树搜索，开放式探索 | 选题—实验—论文—评审 | 首篇全 AI 论文通过 ICLR 2025 workshop 评审 |\n| Agent Laboratory | AMD＋约翰斯·霍普金斯大学 | PhD/Postdoc/ML 工程师/Professor 四代理分工 | 文献综述—实验—报告 | 研究成本下降 84% |\n| MatBrain | 中科院深圳先进院 | 30B 推理模型＋14B 执行模型双协作，Mat-MCP 工具平台 | 材料结构生成—筛选—验证 | 准确率较大模型提升 66%；部署成本降超 95% |\n\n## 五、对高校信息中心意味着什么\n\n第一，**编排能力正在从院系自研走向校级服务**。CERNET\"主任谈\"栏目梳理的西安交通大学、南开大学、西安电子科技大学、同济大学四校实践显示，高校智能体建设的共同问题已从\"要不要建\"转向\"广撒网培育生态还是集中力量打造标杆\"；上海交大网络信息中心与华为合作的\"致远一号\"智能体模式（2026 年 4 月研讨会吸引全国 30 多所高校参与，以\"云养虾\"等真实场景做规模化验证）说明，校级智能体平台完全可以同时承载科研、教学与管理场景。政策端，教育部在 2026 年 3 月 31 日国家教育数字化战略行动部署会上明确以\"人工智能+教育\"推动全场景融合——科研智能体是其中最难也最有显示度的部分。\n\n第二，**工具协议是新的\"系统接口\"**。国家超算互联网的 MCP 工具、MatBrain 的 Mat-MCP 平台、Co-Scientist 的设备指令转换，本质上都在做同一件事：把数据库、计算软件、实验设备封装成智能体可调用的标准工具。高校信息中心手里握着校级 HPC 集群、正版软件、仪器预约系统——这些正是科研智能体最缺的\"手和脚\"。谁先把校内科研工具 MCP 化，谁的智能体生态就有先发的供给优势。\n\n第三，**成本结构决定了轻量化路线的可行性**。MatBrain 用 30B+14B 的组合把部署成本压低 95%，意味着院级工作站也能跑科研智能体；而\"大圣\"、Co-Scientist 这类全流程系统仍依赖大规模算力与实验室改造。高校不必二选一：文献问答与综述类场景用轻量模型加检索即可（OpenScholar 路线），湿实验闭环再接入校级平台。\n\n## 给高校的可操作清单\n\n1. 盘点校内可被智能体调用的科研工具（计算软件、数据库、仪器预约、高性能集群接口），制定 MCP 化封装的优先级清单，先从调用量最大的十件工具做起。\n2. 在校级 AI 平台上开出一个\"科研智能体工作区\"，支持课题组用对话式工具搭建专属智能体，并接入统一的模型网关与 Token 计量，避免各院系重复采购。\n3. 参照上海交大 SciMaster 的做法，同步建设智能体评测基准：至少覆盖引用准确率、工具调用成功率、任务完成率三个指标，将其纳入采购与验收标准。\n4. 把\"结论与实验日志逐条比对\"写入科研智能体的可信要求，参考 Co-Scientist 的双盲评审机制，对涉及发表的智能体产出建立留痕审计。\n5. 与国家超算互联网等公共平台建立合作而非竞争关系：校级平台负责身份、计费与工具封装，公共平台提供弹性算力与成熟智能体市场，善用其最高 50 万元经费或等额算力的伙伴激励。\n6. 在图书馆或学科服务中心部署文献检索增强型智能体（OpenScholar 一类的开源路线），优先解决综述与情报订阅的引用幻觉问题，这是投入产出比最高的第一步。\n7. 为科研智能体制定分级授权：纯文献任务开放给全体师生，涉及真实实验设备与危险试剂的任务保留人工审批环节，参照\"活化污泥工作流\"中\"授权批准\"环节的人工卡点设计。\n8. 用真实场景赛事拉动生态：借鉴上交大智能体大赛（44 校 160 余队）的模式，把校内分散的课题组需求转化为可复用的技能包与智能体模板。\n\n## 还没解决的问题\n\n1. **实验反馈周期与智能体节奏不匹配。**伦敦大学学院汪军教授在港科大峰会上指出，机械臂损坏、设备故障会中断实验，化学与材料实验的反馈周期以天计，与 AI 的快速推理形成结构性矛盾；缺乏对应的理论与方法支撑。\n2. **纯数据驱动难以捕捉物理规律。**港科大陆萌茜团队的经验显示，超 15 天的气象预报稳定性较差，AI 与物理模型的深度融合仍是未完成课题；材料、气候等复杂系统尤其明显。\n3. **评测标准远未收敛。**各家平台的\"效率提升\"口径互不可比——\"6 小时等于博士 1—3 个月\"与\"成本下降 84%\"来自不同任务、不同基线，高校目前没有跨平台可比的第三方评测。\n4. **跨学科复合型人才缺口。**既懂领域科学又掌握智能体工程的人，正是建设与运营这类平台的主力，而这恰是高校信息中心当前最难招聘的岗位类型。\n5. **知识产权与学术伦理规则滞后。**AI 主导完成的实验与论文在署名、专利归属、责任认定上尚无公认框架，Co-Scientist 拒绝 98.7% 有害请求的安全机制也提示：恶意或高危研究请求的治理，需要在校级层面提前设防。\n"},"report-tech-frontier":{"id":6,"slug":"report-tech-frontier","title":"技术侧写：科学大模型的代表成果，与影响选型的三个新变量","kind":"report","dek":"气象三条路线（伏羲的端到端、风乌的多模态、NowcastNet 的神经演变算子），机器化学家与 E2GNN 的可解释路径，Evo 与女娲的领域基础模型——以及 Terminal-Bench-Science 从 20% 跳到 65% 之后，高校该怎么重新算选型这笔账。","tags":["伏羲","风乌 GHR","NowcastNet","机器化学家","E2GNN","Evo 基因组模型","Terminal-Bench-Science"],"sources":[{"url":"https://lygw.ai/blog/20250904-ai4s/","date":"2025-09-04","site":"lygw.ai","title":"国内高校 AI4S 实践凝练与洞察：从“范式革命”到“务实深耕”"},{"url":"https://www.thepaper.cn/newsDetail_forward_29355037","date":"2026-08-29","site":"澎湃新闻 · 学术头条","title":"Science 最新封面：AI 大模型跨越物种边界、解码生命“密码全书”"},{"url":"https://segmentfault.com/a/1190000048257000","date":"2026-09-02","site":"SegmentFault 思否","title":"最强模型 Claude Fable 5.1 发布：科研跑分翻倍，缓存成本骤降 75%"},{"url":"https://finance.sina.com.cn/tech/roll/2026-09-04/doc-iniqrpqy0847298.shtml","date":"2026-09-04","site":"新浪科技","title":"OpenAI 最强模型 GPT-6 Astra 发布"},{"url":"https://cloud.tencent.com/developer/news/4558971","date":"2026-09-04","site":"腾讯云开发者社区","title":"AI 大模型：OpenAI GPT 6 Astra 发布，推理跑分接近饱和"},{"url":"http://finance.eastmoney.com/a/202308192818121790.html","date":"2026-09-01","site":"东方财富网","title":"深势科技完成新一轮融资，将 AI for Science 引入大模型时代"},{"url":"https://cn.chinadaily.com.cn/a/202501/09/WS678473baa310b59111dad6f7.html","date":"2025-01-09","site":"中国日报网","title":"科学大模型：“上线”之路还有多远"},{"url":"https://finance.eastmoney.com/a/202411123237446794.html","date":"2026-08-30","site":"东方财富网","title":"上海首发四款垂直大模型，聚焦 AI 与基础科学研究的融合发展"},{"url":"https://local.cctv.com/2025-04-30/ARTIh8e9J1YO2eEvWIUMX4Kb250430.shtml","date":"2025-04-30","site":"央视网","title":"复旦漆远：共建科学智能开放生态"}],"region":"国内外","layers":["tools","data"],"issue_no":null,"pinned":false,"word_count":5668,"published_at":"2026-09-05T15:24:59.459+00:00","body_md":"## 一、为什么需要一份\"技术侧写\"\n\n平台与建制决定 AI4S 能不能跑起来，模型与算法决定跑到什么水平。这份侧写不追求覆盖全部成果，只挑三类信息：**代表性模型的技术路线**（可复用）、**公开评测结果**（可比较）、以及**通用大模型在科学基准上的最新变化**（影响高校选型）。\n\n## 二、气象：三条技术路线的分野\n\n气象是 AI4S 最早跑出颠覆性成果的领域。传统数值天气预报（NWP）计算成本高昂且提升缓慢，AI 大模型改变了这个局面。国内三支代表性队伍走出了三条不同路线。\n\n### 复旦\"伏羲\"：端到端优化\n\n目标非常明确——直接挑战并超越全球标杆、欧洲中期天气预报中心（ECMWF）的高分辨率预报（HRES）。按 ECMWF 实时评测，\"伏羲\"已成为综合预报精度最高的模型之一。\n\n核心创新是**端到端架构**：不只是预报模型，而是集成资料同化与预报的完整系统，能直接对预报结果做端到端优化，避免传统方法中同化与预报环节割裂导致的误差累积。模型结构采用基于 U-Net 与 Transformer 的 **U-Transformer** 架构，并通过**级联（Cascade）方式**整合多个模型分别优化不同预报时段，提升整体预报时长与精度。\n\n工程与业务侧的公开记录：参与中国气象局示范计划时，16 项指标中 12 项单项指标、3 项综合指标长期位居榜首；团队不仅用开源数据训练，还把预测数据与气象大数据开源；实现四季节预报，关键指标有效时长显著提升；获国际基础科学大会 2025 年度科学前沿奖。协作模式是典型的\"高校 + 研究院 + 国家机构\"：复旦大学（AI3 研究院、大气与海洋科学系）、上智院、中国气象局。\n\n### \"风乌\"：多模态多任务\n\n由上海人工智能实验室联合中国科学技术大学、上海交通大学、南京信息工程大学、中科院大气物理研究所及上海中心气象台共同发布，主攻高分辨率与长时效。最新版本 **风乌 GHR** 把有效预报时间提升至 11.25 天、预报分辨率提升至 10 公里级别，在 80% 的评估指标上超越 DeepMind 的 GraphCast。\n\n技术路线核心是**多模态多任务深度学习**：把气温、风速、气压等不同大气变量视为独立\"模态\"，采用多模态 Transformer 架构处理，以更深入地挖掘变量间的复杂关联。组织形式是\"新型研发机构牵头、多方参与\"。\n\n### 清华 NowcastNet：物理规律嵌入神经网络\n\n与前两者关注中长期预报不同，NowcastNet 专注短时强降水、冰雹等极端天气的**临近预报（0—6 小时）**，成果发表于《Nature》。\n\n最大亮点是**数据驱动与物理驱动的深度融合**。传统 AI 气象模型常被诟病为缺乏物理可解释性的\"黑箱\"，该团队创建了模拟降水物理过程中尺度运动的**\"神经演变算子\"（Neural Evolution Operator）**，无缝嵌入深度学习网络——相当于给模型注入物理学知识，使其既能从数据学模式，又遵循大气运动基本规律，在预测小概率极端事件时更可靠。合作方是国家气象中心、国家气象信息中心等业务单位。\n\n**可复用结论**：架构创新（U-Transformer + 级联）、多模态融合（把物理量当模态）、物理知识嵌入（神经算子）是三条可组合的路线。对高校而言，第三条路线门槛最高但科学价值最大，也最能回应\"不可解释\"的质疑。\n\n## 三、材料与化学：机器化学家与高效势函数\n\n### 中科大\"机器化学家\"：软硬件一体的自主实验平台\n\n目标是打造能模拟甚至替代人类科学家做化学实验的智能平台，实现从文献理解、假设提出到实验执行、结果分析的全流程自动化。平台不是单一软件，而是**软硬件深度融合的系统**：硬件集成高精度机械臂、视觉系统与各类自动化实验模块；软件核心是能自主学习决策的 AI 大脑。\n\n量化能力：可在两周内学习 5 万篇学术论文，六周内验证超过 376 万种实验配方；平台能在一两周内完成人类科学家可能需要一生才能完成的筛选工作。\n\n标志性成果是破解了困扰多相催化领域近 50 年的**\"金属-载体相互作用\"（MSI）**难题：先汇总大量文献实验数据，再用可解释 AI 算法（结合压缩感知与领域知识）从高达 300 亿个数学表达式中筛选出能准确描述该作用的物理控制方程；过程中\"复原\"了缺失的实验数据，并发现\"金属-金属相互作用\"这一全新关键变量，提出具有普适性的\"强金属-金属作用原理性判据\"，成果发表于《Science》。\n\n**方法论价值**：可解释 AI + 压缩感知 + 领域知识，是从\"黑箱预测\"走向\"发现物理规律\"的一条已验证路径。\n\n### 北大 E2GNN：又快又准的原子间势\n\n分子动力学模拟的核心环节是精准高效地预测原子间相互作用势能。传统方法要么精度高但慢（第一性原理计算），要么快但精度不足。北大团队的**等变图神经网络 E2GNN** 在多个基准上超越现有代表性模型，成果发表于《npj Computational Materials》。\n\n技术关键是**对物理对称性（等变性）的巧妙处理**：能量预测必须对体系旋转平移保持不变，力的预测则需随之等变；传统模型为实现这点常依赖复杂的高阶张量运算，开销巨大。E2GNN 采用简洁的**\"标量-向量\"混合表示**编码等变特征，并引入**全局消息传递机制**精确捕捉长程原子相互作用，在满足物理约束的同时极大提升效率。\n\n效果：基于 E2GNN 力场对固态（LiPS）、液态（H₂O）、气态（CH₄）体系的模拟，预测精度可达昂贵的第一性原理计算级别，速度快了几个数量级。\n\n### 深势科技的预训练模型体系\n\n深势科技把 AI4S 带入\"预训练模型时代\"，三条主线值得追踪：**Uni-Mol** 分子表征大模型（在 OGB-LSC 量子化学性质预测任务上夺冠，服务制药、催化、OLED 等场景）、**Uni-RNA**（提升 mRNA 疫苗设计、RNA 结构预测、ASO 开发、siRNA 疗法、靶向 RNA 小分子、Aptamer 研发等几乎所有 RNA 相关场景的模型能力）、**DPA 预训练模型**（提升深度势能模型的场景迁移与泛化能力，已在高性能合金、半导体及电池材料设计中验证领先性）。这些模型通过玻尔（Bohr）平台向高校供给，武汉大学数智教育实践创新平台的算力即由该平台支持。\n\n## 四、生命科学与医药\n\n### 复旦 CRAFTS：给冷冻电镜装\"导航\"\n\nRNA 的复杂三维结构决定生物学功能，冷冻电镜是解析关键技术，但海量 RNA 序列中只有极少数能形成稳定结构，实验筛选成本极高。复旦孙思琦团队的 **CRAFTS** 通过**对比学习**先在庞大的 Rfam 数据库上学会区分哪些序列对属于同一 RNA 家族（领悟决定结构共性的深层特征），再在已知有结构/无结构的 RNA 序列上微调，从而判断任意新序列形成稳定结构的可能性，成果发表于《Science》。这相当于给高成本实验装了低成本导航。\n\n### 上智院的领域大模型群\n\n复旦大学与上智院共同研发的**\"女娲\"系列生命科学大模型**构建了全球首个百亿级参数 RNA 基础模型，其中生物结构大模型支持蛋白质与抗体药物开发；**基因导航大模型**结合图神经网络与调控关系知识图谱提升基因调控预测精度；**生命流体大模型**以全球最大器官流体力学数据库为基础，大幅提升流体模拟效率，用于脑动脉血流等疾病机制研究；**\"观心\"**是全国首个 AI 心脏大模型。2024 年 11 月的科学智能创新论坛还发布了中国首个自主研发的气候科学大语言模型 **Planet Intelligence @ Climate**。\n\n### 清华成像与智能技术实验室：破解医疗 AI 落地三难\n\n医疗 AI 面临三个结构性障碍，清华给出的解法值得信息中心参考：\n\n1. **数据孤岛**（隐私导致难共享）→ 发展**联邦学习**等隐私计算技术，实现多中心联合训练而不共享原始数据，代表性成果发表于《The Lancet Digital Health》；\n2. **标注成本高**（需大量专业医生）→ 开发**弱监督学习**算法，例如让 AI 直接从医生书写的自由文本诊断报告中学习、自动检测 CT 颅内异常，避免像素级精细标注，成果发表于《Cell Reports Medicine》；\n3. **重复开发**（每种疾病/模态都要专用系统）→ 构建**单模态多任务基础模型**，\"一个模型通解多种问题\"，成果见于《Nature Medicine》《Patterns》等。\n\n### 地球科学与数学\n\n- **元古大模型**（中国地质大学（武汉），2024 年 12 月 7 日发布）：地球科学领域垂直大模型，可对古生物化石进行复原；\n- **\"坤元\"**：全球首个多模态地理科学大模型，被称为\"智能地理学家\"；\n- **亲吻数问题**：2026 年上智院联合北京大学、复旦大学团队，用 AI 在这一经典数学难题上取得系统性突破——数学长期被视为 AI 最难介入的领域之一，这一结果具有指标意义。\n- 智源研究院的生物计算大模型搭建了**全球首个数字孪生心脏电功能超实时仿真系统**，包含 19 种细胞生理状态变量和 70 多个公式。\n\n### 基因组基础模型 Evo（海外对照）\n\n斯坦福大学 Brian L. Hie 团队以封面文章形式在《Science》发表 **Evo**：基于 **3000 亿 DNA token** 训练的大规模基因组基础模型，能在长序列的单碱基分辨率下预测与生成 DNA、RNA 和蛋白质序列，跨物种基因预测超越特定模型。模型专为捕捉生物学两个核心方面设计——中心法则的多模态性与进化的多尺度特性。Evo 生成的多基因系统成功率接近 50%，生成的 CRISPR-Cas9 蛋白经实验验证具有功能活性，全基因组生成结果在基因组组织、编码密度上与天然基因组高度相似。评论者的评价是：\"首次从进化多样性中提取出 DNA 的'语法规则'。\"\n\n**对高校的提示**：Evo 的训练规模意味着这类\"生命基础模型\"只能由具备大规模算力与数据的机构产出，多数高校的合理策略是**接入 + 微调 + 领域适配**，而不是自研底座。\n\n## 五、通用大模型的科学能力：正在剧烈变化的一格\n\n高校选型的另一条线是通用大模型在\"自主科学研究\"基准上的跃升。2026 年 9 月的两次发布值得记录。\n\n**Anthropic Claude Fable 5.1 / Mythos 5.1**（2026 年 9 月 2 日）：在衡量自主科研能力的 Terminal-Bench-Science 0.1 上得 52.6%，而上代 Fable 5 为 24.7%、GPT-5.6 Sol 为 22.4%——**一个数量级的跳变**；Terminal-Bench 4.0 代码工程能力从 42.0% 升至 55.8%（Mythos 版 60.9%）；缓存读取价格同步骤降 75%，高强度 Agent 任务总成本最高可省 45%。Mythos 5.1 与 Fable 共用权重，但开放更高风险能力上限，仅向通过 Cyber Verification Program（CVP）与 Life Sciences Verification Program（LSVP）审核的美国机构开放。**生命科学方向设专门审核通道**，说明高风险科研能力已经开始分级供给。\n\n**OpenAI GPT-6 Astra**（2026 年 9 月 4 日）：Terminal-Bench-Science 0.1 得 64.6%，高于两天前的 Fable 5.1，且完成同等任务的估计 API 成本低约 31%（更低成本设置下仍得 61.1%）；Terminal-Bench 4.0 得 57.9%；FrontierMath Tier4 得 97.6%；ARC-AGI-3 得 99.9%（GPT-5.6 Sol 为 7.8%，人类水平约 48%）；OSWorld 2.0 得 72.6%，单项任务平均耗时从约 75 分钟缩短到 40 分钟。OpenAI 称 Astra 已帮助解决数学领域长期存在的开放性问题，包括在素数间隔研究中取得两个新的理论结果。定价为每百万输入 token 10 美元、输出 50 美元（为前代 2.5 倍），提供速度提升 2.5 倍的快速模式。\n\n**这对高校意味着什么**：\n1. **科研 Agent 的可用性阈值被跨越**。Terminal-Bench-Science 从 20% 量级跳到 50%—65%，意味着\"让模型自己跑一段科研流程\"从演示变成可评估选项。\n2. **成本结构在重构**。缓存读取降价 75%、Prompt 缓存减免输入 Token 计费，直接改善高校\"统一兜底 Token 成本\"模式的可持续性。\n3. **合规与分级供给成为新变量**。生命科学高风险能力需要机构审核（LSVP），国内高校在采购海外模型用于生物、化学等敏感方向时会遇到额外门槛，反过来会加强本地化部署与国产模型适配的动力。\n4. **选型要看\"单任务成本\"而不是单价**。GPT-6 Astra 单价是前代 2.5 倍，但因输出 token 减少、执行时间缩短、重试次数降低，多项基准估算的单任务成本反而下降。校级平台计费策略应据此从\"按 Token 定额\"转向\"按任务预算\"。\n\n## 六、还没解决的技术瓶颈\n\n- **AI 幻觉与可解释性**：大模型可能生成看似合理但完全错误的结论；即使是表现惊艳的模型，其背后原理也难以说清。在要求严谨、可复现的科学研究中，不可解释的\"黑箱\"是重大隐患。NowcastNet 的神经算子与中科大的可解释 AI 是两条有效路径，但都还属个案。\n- **物理知识与数据驱动的耦合**：把数百年积累的物理、化学、生物知识有效融入数据驱动模型，是提升可靠性与泛化能力的关键，简单拼接或完全抛弃物理规律都不是最优解。\n- **通用性与开发成本的矛盾**：AlphaFold 一类的成功多是针对特定科学问题的专用模型，通用 AI 科研工具仍然稀缺、开发成本高昂，难以像 Python 那样成为普惠的科研基础设施。北大林周辰教授的这一判断，解释了为什么\"星河启智\"要把 400 余个模型与工具、Intern-Discovery 要把 200 余个智能体集中开放——**用平台规模对冲单点工具的通用性不足。**\n- **模型评测体系仍在早期**：上智院把\"科学大模型评测体系\"列为四大重点布局之一，说明连头部机构也认同学界缺乏公认的科学模型评测标准。高校在选型时应自建小规模领域基准，而不是直接采信厂商跑分。\n"}});
window.__AI4S_API__.articleDetails=Object.assign(window.__AI4S_API__.articleDetails||{},{"report-token-service":{"id":2,"slug":"report-token-service","title":"Token 即基础设施：高校信息中心的大模型统一服务实践","kind":"report","dek":"清华 easycompute 的券化算力与免申请自动续期、“清小答”由学校兜底 Token 成本、农大本地化部署 4 小时 5700 万 Token、武大 40 门课的 AI 实训基地；再加上网关、四角色对账与 Token 成本失控的治理清单。","tags":["Token 服务平台","MaaS","算力券","大模型 API 网关","配额与全成本核算","知识库众包运营"],"sources":[{"url":"https://m.sohu.com/a/1049819293_121124031/","date":"2026-07-13","site":"搜狐网","title":"@全体 THUer 续上了！清华专属免费算力持续可用"},{"url":"https://www.toutiao.com/w/1870693389993028/","date":"2026-07-15","site":"今日头条","title":"清华大学为全校学生配备 AI 学伴“清小答”"},{"url":"https://news.cau.edu.cn/zhxwnew/f007b38d5f7b4b35a0e1a536088e1665.htm","date":"2025-02-21","site":"中国农业大学新闻网","title":"中国农业大学 AI 大模型平台正式上线"},{"url":"https://uc.whu.edu.cn/info/1646/118851.htm","date":"2025-03-04","site":"武汉大学本科生院","title":"携手 DeepSeek，数智武大：数智教育实践创新平台重磅升级"},{"url":"https://lib.sustech.edu.cn/2026/0904/c1405a8371/page.htm","date":"2026-09-04","site":"南方科技大学知识苑","title":"Trial on the LeapSpace AI Platform"},{"url":"https://juejin.cn/post/7666019880677523465","date":"2026-07-27","site":"掘金","title":"MAI Gateway｜AI 网关如何解决高校课题组和实验室共享模型的账目问题"},{"url":"https://www.geekpark.net/news/363815","date":"2026-05-08","site":"极客公园 / IDC","title":"2025 大模型公有云服务：中国企业级 MaaS 市场 Token 调用量"},{"url":"https://blog.csdn.net/weixin_33212799/article/details/164279548","date":"2026-09-01","site":"CSDN","title":"大模型 Token 成本失控：预算配额、用量监控与告警体系建设指南"},{"url":"https://blog.csdn.net/weixin_44661794/article/details/162974878","date":"2026-08-24","site":"CSDN","title":"大模型 API 网关统一管控架构实战：多模型接入、计费统计"},{"url":"https://blog.csdn.net/gitblog_01164/article/details/163499879","date":"2026-08-05","site":"CSDN","title":"new-api：新一代 AI 模型网关与资产管理平台"}],"region":"国内为主","layers":["model","compute"],"issue_no":null,"pinned":true,"word_count":3990,"published_at":"2026-09-05T15:24:58.626+00:00","body_md":"## 一、为什么是 Token：从\"买卡\"到\"发额度\"\n\n国家数据局把 Token（词元）称为\"智能时代的价值锚点\"，是连接技术供给与商业需求的**结算单位**。这个定义放到高校场景里非常贴切：对师生来说，AI 能力的最小可分配单位不是 GPU 卡时，而是一次调用消耗的 Token。\n\nIDC 披露的数据可以说明量级变化：2024 年中国企业级 MaaS 市场按调用量统计为 114 万亿 Tokens，2025 年跃升至 1944 万亿 Tokens，同比增长约 16 倍；IDC 预计 2026 年还会同比增长约 20 倍到 40000 万亿 Tokens。驱动力是多模态成熟与 Agent 类应用规模化落地——每一次交互消耗的 Token 量级都在抬升。\n\n对高校信息中心来说，这意味着一件事：**大模型不再是\"上个聊天机器人\"的项目，而是要当成水电网一样的校内公共服务来发额度、做计量、控成本。** 一个直观的数字来自中国农业大学：其 AI 大模型平台上线 4 小时，2400 位师生体验、提问 7200 次、消耗 Token 5700 万。按这个速率外推，全校师生常态使用后的 Token 消耗是必须提前规划的预算项。\n\n## 二、四种在校内落地的服务形态\n\n### 形态一：统一身份 + 算力券 + MaaS（清华大学 easycompute）\n\n清华的做法把\"发额度\"工程化了。师生登录后通过统一身份认证进入 easycompute 平台，点击\"登录领券/使用\"即自动发放 1000 元算力券，可在\"我的优惠券\"中查看使用；无需填表申请、无需重新申领、无需导师审批，系统统一自动更新有效期。2026 年暑期该券在首轮延期基础上再次续期至 8 月 31 日，账户内未用完的余额与权益完整保留，配套的智能编码福利同步续期（套餐有效期 3 个月）。\n\n平台侧持续开放 4090、5090 等全系主流 GPU 算力，内置一站式大模型 MaaS 服务，支持海量 Token 高效调用，适配大模型微调、长文本推理、智能体交互等高频场景；主流 AI 框架、开发环境与常用数据集提前预装、开箱即用。使用规则也写得很清楚：算力券仅限本人用于校内课程学习、学术科研、科创实践等非营利用途，禁止转借、倒卖与违规占用。\n\n这套设计的可复用点是三条：**券化额度**（预算可视、可延期、可结转）、**统一身份直通**（零申请门槛）、**环境预装**（把\"搭环境\"这一最大隐性成本前置消化）。\n\n### 形态二：学校统一承担 Token 成本（清华\"清小答\"）\n\n同样是清华，面向学生的\"清小答\"走的是另一条路：2024 年 8 月 14 日新生开学第一天上线，基于大模型智能体技术，覆盖选课指导、生活问题、科研答疑、数据分析、PPT 制作等从入学到毕业的全周期场景，**由学校统一承担 Token 成本，学生免费无限使用**。\n\n这是\"普惠型\"与\"配额型\"的分野：面向全体学生的通用助手由学校兜底、不限额；面向科研的重负载训练与推理则发券、按额度管理。两者并行，而不是二选一。\n\n### 形态三：本地化部署的校级大模型平台（中国农业大学）\n\n中国农业大学 AI 大模型平台于 2025 年 2 月 21 日在 PC 端与移动端同步上线，依托学校智算平台算力资源**本地化部署**，支持 DeepSeek-R1、Qwen2.5、Qwen2-VL、Conan-embedding-v1、CosyVoice-300M-SFT、SenseVoiceSmall、Flux.1-dev 等主流模型，覆盖对话、多模态问答、语音合成与识别、文生图。入口做了三路打通：独立网址 ai.cau.edu.cn、学校综合服务平台\"推荐服务—AI大模型\"、移动端企业号。\n\n在此基础上，信息化团队同步开发了\"小鹉哥\"智能体，用于助教、助学、助研、助管。值得关注的是知识库的运营机制：校内知识库尚不完备时，师生可在网上办事大厅的\"981 AI大模型知识库征集\"提交问题与权威答案，由网络技术中心审核后入库。**把知识库建设做成众包 + 审核的常态化流程**，比一次性建库更可持续。\n\n### 形态四：面向教学的 AI 实践平台（武汉大学 × 深势科技）\n\n武汉大学数智教育实践创新平台由深势科技定制，2024 年 9 月上线，落实\"五位一体\"\"四真计算\"\"三教融合\"的数智教育理念；2025 年 2 月重磅升级，正式接入 DeepSeek 系列大模型。平台已有超过 40 门课程上线、累计发布 AI Note 超过 2000 篇、服务师生超过 4000 人，定位为全学科 AI 教学实训基地，并由深势科技玻尔（Bohr）平台提供算力支持。\n\n两个具体做法有借鉴意义：**AI Note**（交互式学习环境，模型生成可视化代码示例，学生走\"理论→实践→反馈\"闭环，例如在可视化界面观察不同优化器对收敛速度的影响）；**AI 助教\"珞珞\"**（动态构建学生学习画像，结合课程内容提供个性化问答，引导\"问题发现—自主探究—认知重构\"的思维训练，并能按学习轨迹推荐补充资料）。师生可在同一平台完成图文教学、代码实训、科研竞赛与科研计算，实现学练一体、研学一体。\n\n此外，图书馆系统也在补位：南方科技大学图书馆于 2026 年 9 月开通 Elsevier LeapSpace 科研级 AI 工作空间试用（9 月 7 日至 10 月 6 日，首次使用需在校内 IP 范围注册），平台汇聚 2000 万余篇全文同行评议文章与图书、超过 1000 家内容伙伴、1 亿余条 Scopus 学术记录，覆盖 7000 多家出版商与 330 个学科，且每个 AI 回答都附带引用与原文链接以便溯源。**采购带引用的科研 AI 空间，是图书馆参与 AI4S 基础设施的低成本入口。**\n\n## 三、Token 服务的治理层：网关、配额与账单\n\n一旦多院系、多课题组接入，平台就会遇到与企业 AI 中台完全相同的问题：接口地址零散、业务代码硬编码模型地址与密钥、Token 消耗统计分散在各处、对内成本核算与对外账单对账困难、异常高频调用挤占算力、Prompt 模板散落与敏感内容直接入模。\n\n行业实践给出的答案是**统一大模型 API 网关**：所有 LLM、Embedding、重排、图像生成接口统一收口，实现路由、鉴权、计费、限流、内容安全审核、Prompt 模板托管一体化管控。开源侧的 new-api / One API 一类项目支持把多家上游转换成 OpenAI 兼容或 Anthropic 兼容格式，配内部充值、配额分配、按请求与按用量计费、缓存命中统计等能力。商业侧的 MaaS 网关则强调统一 OpenAI 格式接口、仅改 `model` 字段即可切换模型、全局 Prompt 缓存带来的输入 Token 计费减免（实测综合成本最高可降 60%—70%）、以及可视化调用监控（调用次数、Token 消耗、首包时延、成功率、异常报错）。\n\n高校场景还有一个企业没有的难点：**一笔模型费用里有四个角色**。学生可能是付款人（先垫付再找导师报销），导师是经费负责人，真正承担费用的是某个纵向/横向项目或校内基金，而实际调用可能来自共享服务器上的批处理脚本。到学期末，付款人、使用人、经费项目、研究任务对不上，账自然难算。常见的错误做法是把一把 Key 放进服务器、代码和课题组群里共用。\n\n大型仪器共享平台早就解决过类似问题：导师建立课题组，学生以个人身份加入，使用记录落到具体成员，费用按项目归集。模型 API 更该被当成\"共享仪器\"而不是\"办公软件\"来管理——**项目—成员—令牌—配额—调用记录五元组对齐**，才能同时满足科研便利与财务合规。需要明确说明边界：网关可以生成用量明细、解释钱怎么花出去了，但不能把供应商账单变成合规票据，也不能替财务判断某笔个人订阅是否属于可报销范围。\n\n## 四、成本失控的真实形态与检查清单\n\nToken 成本失控通常不是在选型那一刻决定的，而是在调用量上来之后悄悄发生的。计量口径要先分清楚：中文一个汉字通常对应 1—2 个 Token，英文一个单词可能被拆成一个或几个 Token，代码里的空格、缩进、符号都可能独立成 Token，所以同一段提示词在不同模型间实际消耗并不同——估算不能只看字符数，要看模型返回的 `usage` 字段与服务商计费口径。单次请求成本 = 输入 Token × 输入单价 + 输出 Token × 输出单价，而 Agent 场景会把历史对话、工具返回结果反复塞进上下文，形成乘数效应。\n\n给高校信息中心的落地清单：\n\n1. **分层发额度**：面向全体师生的通用助手由学校兜底不限额（普惠）；面向科研的重负载走算力券/Token 配额（可计量、可延期、可结转）。\n2. **统一入口**：一个 OpenAI 兼容网关，纳管多家模型与本地部署模型；切换模型只改 `model` 字段。\n3. **令牌到人、账到项目**：个人身份认证领券，Key 不共享；调用记录关联项目编号，供财务对账。\n4. **配额 + 超额双策略**：预设配额按测算申请经费并定期充值，同时与服务商约定超额使用，避免高峰期服务中断（上海科技大学实践）。\n5. **缓存优先**：系统提示词与固定 Schema 做全局 Prompt 缓存，长上下文场景做 KV 缓存分片优化。\n6. **监控与告警**：把调用次数、Token 消耗、首包时延、成功率、异常报错做成可视化看板，设预算阈值告警。\n7. **知识库众包**：像农大那样把知识补全做成常态化的征集—审核—入库流程，答案质量决定服务口碑。\n8. **合规前置**：网关层做输入内容审核与敏感拦截，涉密与隐私数据不进公共模型，必要时走本地化部署。\n\n## 五、观察与判断\n\nToken 服务平台正在成为高校信息中心的\"新基建标配\"，但真正拉开差距的不是接了多少模型，而是三件事：**额度发放是否零门槛、调用记录是否能对到项目、知识库是否有常态化运营机制**。前者决定使用率，中者决定可持续性，后者决定服务质量。\n\n下一阶段的变量在成本侧：随着 Agent 类应用把单次交互的 Token 量级抬升一个数量级，\"学校统一兜底\"的模式会越来越贵。可以预期的演进是按人群与任务分级定价、把缓存命中率纳入平台 KPI、以及把校内推理负载逐步迁移到本地部署与国产算力上。\n"},"weekly-2026-08-31":{"id":7,"slug":"weekly-2026-08-31","title":"周度综述（建库首期）：高校把平台服务化，海外把基建国家化，模型层科学基准跳一个量级","kind":"weekly","dek":"上海大学公开 AI 智慧平台的建设逻辑，南科大图书馆引入带引用的科研 AI 工作空间，江苏揭牌全国首个省级 AI4S 公共算力中心；NSF 启动州与区域 AI 基础设施中心计划；Terminal-Bench-Science 从 20% 量级跳到 50%—65%。","tags":["上海大学","南方科技大学","江苏 AI4S 算力中心","NSF Hub 计划","Fable 5.1","GPT-6 Astra"],"sources":[{"url":"https://cernet.edu.cn/info/focus/rd_xin_wen/202608/t20260820_2766409.shtml","date":"2026-08-20","site":"中国教育和科研计算机网 CERNET","title":"上海大学：怎样建好、用好 AI 智慧平台"},{"url":"https://lib.sustech.edu.cn/2026/0904/c1405a8371/page.htm","date":"2026-09-04","site":"南方科技大学知识苑","title":"Trial on the LeapSpace AI Platform"},{"url":"https://www.sohu.com/a/1069781691_121901402","date":"2026-08-31","site":"搜狐网","title":"AI4S 赋能科研创新：江苏打造全国首个省级公共算力中心"},{"url":"https://www.idcpc.cn/post/2016.html","date":"2026-09-01","site":"IDCPC","title":"中国移动-浙江大学启真算力中心"},{"url":"https://finance.eastmoney.com/a/202506233438033561.html","date":"2026-08-30","site":"东方财富 / 上观新闻","title":"定义 AI4S 的未来标准 上海交通大学发布超级科研平台"},{"url":"http://smse.whut.edu.cn/xydt/202608/t20260814_1413959.shtml","date":"2026-08-14","site":"武汉理工大学材料科学与工程学院","title":"腾讯云来院开展 AI for Science 合作交流"},{"url":"https://www.toutiao.com/w/7670852130735686444/","date":"2026-08-06","site":"今日头条","title":"华南农业大学与联想合作搭建 AI 算力平台"},{"url":"https://stem.zjnu.edu.cn/2026/0815/c9134a580020/page.htm","date":"2026-08-14","site":"浙江师范大学","title":"美国 NSF 和区域 AI 基础设施中心将推动全国范围内人工智能科学研究发展"},{"url":"https://carcc.org/2026-08-27/all-things-ai-september-2026/","date":"2026-08-27","site":"CaRCC","title":"All Things AI – September 2026"},{"url":"https://arxiv.org/abs/2608.26519","date":"2026-08-27","site":"arXiv","title":"Report of the 2026 Workshop on Next-Generation Ecosystems for Scientific Computing"},{"url":"https://www.stdaily.com/web/English/2026-08/25/content_568917.html","date":"2026-08-25","site":"Science and Technology Daily","title":"AI for Science Shifts from Efficiency Boost to Systemic Reform of Research"},{"url":"https://segmentfault.com/a/1190000048257000","date":"2026-09-02","site":"SegmentFault 思否","title":"最强模型 Claude Fable 5.1 发布：科研跑分翻倍，缓存成本骤降 75%"},{"url":"https://finance.sina.com.cn/tech/roll/2026-09-04/doc-iniqrpqy0847298.shtml","date":"2026-09-04","site":"新浪科技","title":"OpenAI 最强模型 GPT-6 Astra 发布"}],"region":"国内外","layers":["compute","model","region"],"issue_no":null,"pinned":false,"word_count":4231,"published_at":"2026-09-05T01:00:00+00:00","body_md":"> 本期为观测台首期简报，覆盖近期可核对的公开动态。自下一期起，每天 09:00（Asia/Shanghai）自动抓取最近一日新进展。\n\n## 一句话概览\n\n国内高校的动作集中在**\"平台服务化\"**：上海大学把超算底座包装成面向全校的一站式 AI 智慧平台，南方科技大学图书馆引入带引用的科研 AI 工作空间，江苏揭牌全国首个省级 AI4S 公共算力中心。海外则是**\"国家基建下沉\"**：NSF 启动州与区域 AI 基础设施中心计划，科研计算社区进入 Gateways 2026 与新一轮培训周期。模型层出现一次明显的能力跳变，通用大模型在\"自主科学研究\"基准上从 20% 量级跨到 50%—65%。\n\n## 国内高校\n\n**上海大学：怎样建好、用好 AI 智慧平台。** 中国教育和科研计算机网（CERNET）刊发长文，系统披露上海大学\"千学百科\"AI 智慧平台的建设逻辑：以自建的\"自强5000\"超算中心为算力底座，采用 HPC 技术构建高性能算力集群与**异构算力管理平台**，配可扩展架构与智能资源调度以避免闲置、冲突和浪费；平台设\"千智汇聚\"\"学无止境\"\"百求必应\"\"科创未来\"四大模块，其中**\"科创未来\"面向科研与学习提供一站式大模型和算力开放能力**；同时建设通用大模型训推平台与大模型应用开发平台，提供兼容纳管多领域多厂商大模型的端到端开发工具链，并配套数据集、大模型库与实战教程。在底座之上已推出上海话大模型、类器官大模型、材料基因大模型及智能体等学科垂类模型。\n\n**南方科技大学图书馆：开通 LeapSpace AI 平台试用。** 试用期 2026 年 9 月 7 日至 10 月 6 日，首次使用需在校内 IP 范围完成个人账号注册。LeapSpace 是 Elsevier 面向研究者的科研级 AI 工作空间，基于出版商中立的内容底座，汇聚 **2000 万余篇全文同行评议文章与图书**、超过 1000 家内容伙伴（含 Emerald、IOP Publishing、NEJM Group、Sage），并调用 **1 亿余条 Scopus 学术记录**，覆盖 7000 多家出版商与 330 个学科；每个 AI 生成的回答都附带引用与原文链接，便于研究者溯源核验。对高校而言，这是图书馆以最低成本参与 AI4S 基础设施（可信语料 + 可溯源问答）的典型入口。\n\n**江苏省：全国首个省级 AI4S 公共算力中心揭牌。** 由省数据局、省发改委统筹指导，省教育厅、省科技厅、省财政厅、省卫健委、省国资委共同参与，省数据集团负责建设运营，面向全省高校、科研机构、公立医疗卫生机构和创新创业主体提供普惠、弹性、安全可信的专业化 AI4S 算力服务。目前落实约 **700P 规模化算力**，完成 **223 款算力产品定价上架**；依托省一体化算力监测调度平台实现多元异构算力（国产 + 先进异构）统一纳管、调度与服务；模型服务平台已接入 **70 余款模型并实现 API 调用**，后续集成通用模型库、高质量数据集与训推工具，做到工具、模型、算力\"开箱即用\"。安全侧实行算力专区化与物理隔离，配分级授权、全程审计、动态监测；运营思路为\"市场运营、公益兜底、开放共建\"。\n\n**浙江大学：启真算力中心细节披露。** 中国移动—浙江大学启真算力中心是全国首个校企合营模式算力中心，项目整体建成后浙江大学人工智能算力将达 **711Pflops**，达到全国高校头部水平；后续浙大算力网络将接入中国移动\"百川\"算力并网平台，实现算力资源统一调度与服务普惠。技术上基于移动云底座打造智算超算统一调度平台，整合高性能 CPU、GPU 与国产 AI 芯片，通过 1600Gbps 高速网络与九天人工智能平台开放，实现对通用、超算、智算算力的统一管理与调度，并打通数据、模型训练到推理验证的衔接。\n\n**上海交通大学：超级科研平台三模块。** 平台围绕智慧图书馆、AI for Science 计算中心、分析测试中心三大核心模块，集成全校各学科资源，实现算力、数据、仪器设备的共享与弹性调配，贯通\"从文献到计算再到实验\"的科研闭环。AI for Science 计算中心的异构算力支持\"一键开跑\"，调度系统把算力获取压缩至**分钟级**，本科生也可同时调用校内集群与云端超算完成传统需数月的分子模拟；分析测试中心在建的\"表征超级 OS\"可自动解析电镜、质谱数据并生成三维模型。试运行期间校内科研效率提升 30%、跨学科项目增长 40%。平台规划接入\"东数西算\"工程，成为国家算力网关键节点。\n\n**武汉理工大学材料学院：与腾讯云就 AI4S 建立常态化对接。** 腾讯云副总裁杨晖一行到访，围绕 AI for Science、人工智能赋能教育教学、智慧办公及科研算力交流研讨；双方一致同意发挥学校在材料科学、人工智能与工程应用方面的综合优势，以及腾讯云在云平台、大模型、算力资源和产业生态方面的技术优势，聚焦具体科研问题与实际应用场景，建立常态化沟通对接机制，形成一批具示范意义的合作成果。\n\n**华南农业大学：搭建校级 AI 算力平台。** 与联想合作，以搭载第五代英特尔至强处理器的联想问天 WA5480 G3 服务器为核心搭建新 AI 算力平台，专门解决数字信息与工程学院在数值计算、大模型训练等高并发场景的算力瓶颈。第五代至强芯片自带 AI 加速能力，无需额外加装加速硬件即可支撑两百亿参数大模型的推理调优，配 DDR5 内存与 PCIe 5.0 高速接口；部署后各类仿真与算法计算任务运行效率明显提升，多个课题组可同步开展科研，不必为算力排队。背景是 2026 年山东、郑州、江西等地密集出台算力补贴政策，支持高校加大算力投入。\n\n## 海外\n\n**NSF：启动国家和区域 AI 基础设施中心计划。** 2026 年 8 月 4 日正式宣布，目标是扩大 AI 驱动科学发现所需算力资源的可及性，并强化高校的研究、教育与劳动力培养。各中心需与 NAIRR 等国家层面计划对接，实现资源共享与协同，形成全国性 AI 科研基础设施网络；计划把**师资培训放在核心位置**。配套的网络研讨会第二场于 9 月 2 日举行，介绍技术与慈善组织对申请方的支持。\n\n**CaRCC：All Things AI 九月刊发布。** 校园科研计算联盟更新了 NAIRR 试点与其他 AI 计划的机会、活动与培训清单，包括 Gateways 2026（9 月 9—11 日，华盛顿特区）——科学网关与科研基础设施社区年会，聚焦拓宽计算资源获取的工具、平台与工作流，含教程、论文报告与动手实践环节。\n\n**arXiv：新一代科学计算生态工作坊报告。** 《Report of the 2026 Workshop on Next-Generation Ecosystems for Scientific Computing: Harnessing Community, Software, and AI for Cross-Disciplinary Team Science》（arXiv:2608.26519）于 8 月 27 日提交，作者覆盖美国国家实验室与高校的科研软件、算力与团队科学负责人，讨论社区、软件与 AI 如何在跨学科团队科学中协同。这是观察海外科研软件与算力生态治理的一手材料。\n\n**鄂维南：AI for Science 进入\"下半场\"。** 在 2026 AI for Science Congress（北京）上，中国科学院院士、北京科学智能研究院（AISI）学术委员会主任鄂维南表示，AI4S 正从\"构建 AI 驱动的科研工具\"转向\"重构整个科研生态\"：AI 的价值远不止加速研究，它将结构性地重塑基础研究的生产模式与运行体系。他把当前普遍把 AI 当作科研助手（文献检索、大规模仿真）视为第一阶段即\"科研生产力改善\"，真正的问题是\"AI for Science 之后\"——当技术能力跃升，科研的**组织方式、评价标准与资源配置**该如何系统性重新设计；并以通用软件生态为类比，设想一个整合算力、仿真引擎、领域知识库与自动化实验室的开放、通用科研基础设施。\n\n## 模型层：科学基准出现数量级跳变\n\n**Anthropic 发布 Claude Fable 5.1 / Mythos 5.1（9 月 2 日）。** 在衡量自主科学研究能力的 Terminal-Bench-Science 0.1 上得 52.6%，上代 Fable 5 为 24.7%、GPT-5.6 Sol 为 22.4%；Terminal-Bench 4.0 代码工程能力从 42.0% 升至 55.8%（Mythos 版 60.9%）；**缓存读取价格骤降 75%**，高强度 Agent 任务总成本最高可省 45%。Mythos 5.1 共用相同权重但开放更高风险能力上限，仅向通过 Cyber Verification Program 与 **Life Sciences Verification Program** 审核的机构开放。\n\n**OpenAI 发布 GPT-6 Astra（9 月 4 日）。** Terminal-Bench-Science 0.1 得 64.6%，完成同等任务的估计 API 成本比 Fable 5.1 低约 31%（低成本设置下仍得 61.1%）；Terminal-Bench 4.0 得 57.9%；FrontierMath Tier4 得 97.6%；ARC-AGI-3 得 99.9%（前代 7.8%）；OSWorld 2.0 得 72.6%，单项任务平均耗时从约 75 分钟缩短至 40 分钟。OpenAI 称模型已帮助解决数学领域长期存在的开放性问题，包括素数间隔研究中的两个新理论结果。定价为每百万输入 token 10 美元、输出 50 美元，另提供速度提升 2.5 倍的快速模式。\n\n**对高校 AI4S 平台的三点影响**：其一，缓存降价与 Prompt 缓存减免直接改善\"学校统一兜底 Token 成本\"模式的可持续性；其二，生命科学方向出现机构审核门槛（LSVP），会加强敏感学科的本地化部署与国产模型适配动力；其三，选型应从\"按 Token 定额\"转向\"按任务预算\"——单价上涨但单任务成本可能下降。\n\n## 本期观察：三个可跟进的信号\n\n1. **省级公共算力中心会不会成为省属院校的默认解**。江苏模式已经把\"算力产品定价上架 + 模型 API + 数据集 + 训推工具\"做成一站式供给，若其他省份跟进，自建校级集群的必要性会重新评估。\n2. **图书馆会不会成为\"可信科研 AI\"的采购主体**。南科大引入 LeapSpace 是一条低成本路径：不动算力、不建模型，先把\"带引用的科研问答\"提供给师生。\n3. **AI4S 的\"下半场\"讨论会不会落到考核改革**。鄂维南提出的组织方式、评价标准与资源重配，是比建平台更难、也更决定成败的一环；北大科学智能学院的实体建制与双导师制是目前少数的制度性答案。\n"}});

;(function(){
  var DB = window.__AI4S_API__ || {};
  function matchQ(item,q,fields){
    q=(q||'').trim().toLowerCase(); if(!q) return true;
    for(var i=0;i<fields.length;i++){var v=item[fields[i]];
      if(v && String(v).toLowerCase().indexOf(q)!==-1) return true;}
    return false;
  }
  function paginate(arr,limit,offset){
    offset=offset||0;
    if(limit==null||isNaN(limit)) return arr.slice(offset);
    return arr.slice(offset,offset+limit);
  }
  function toInt(v,def){ v=parseInt(v==null?'':v,10); return isNaN(v)?def:v; }
  function handleSignals(sp){
    var items=(DB.signals||[]).slice();
    var days=toInt(sp.get('days'),0);
    if(days>0){
      var mx=''; for(var i=0;i<items.length;i++){var d=items[i].occurred_on||''; if(d>mx)mx=d;}
      if(mx){var cut=new Date(mx+'T00:00:00Z'); cut.setUTCDate(cut.getUTCDate()-(days-1));
        var cutS=cut.toISOString().slice(0,10);
        items=items.filter(function(s){return (s.occurred_on||'')>=cutS;});}
    }
    var layer=sp.get('layer');
    if(layer&&layer!=='\u5168\u90e8') items=items.filter(function(s){return s.layer===layer;});
    var q=sp.get('q')||'';
    items=items.filter(function(s){return matchQ(s,q,['org','summary','source_title','region']);});
    return {items:paginate(items,toInt(sp.get('limit'),60),toInt(sp.get('offset'),0))};
  }
  function handleCases(sp){
    var items=(DB.cases||[]).slice();
    var country=sp.get('country');
    if(country&&country!=='\u5168\u90e8') items=items.filter(function(c){return c.country===country;});
    var layer=sp.get('layer');
    if(layer&&layer!=='\u5168\u90e8') items=items.filter(function(c){return c.layer===layer;});
    var q=sp.get('q')||'';
    items=items.filter(function(c){return matchQ(c,q,['org','org_en','platform','highlights','country','source_title']);});
    return {items:paginate(items,toInt(sp.get('limit'),200),toInt(sp.get('offset'),0))};
  }
  function handleArticles(sp){
    var items=(DB.articles||[]).slice();
    var kind=sp.get('kind');
    if(kind) items=items.filter(function(a){return a.kind===kind;});
    var q=sp.get('q')||'';
    items=items.filter(function(a){return matchQ(a,q,['title','dek']);});
    items=paginate(items,sp.has('limit')?toInt(sp.get('limit'),null):null,toInt(sp.get('offset'),0));
    if(sp.get('body')==='1') items=items.map(function(a){return DB.articleDetails[a.slug]||DB.articleDetails[String(a.id)]||a;});
    return {items:items};
  }
  function route(path,sp){
    if(path==='/api/facets') return {status:200,body:DB.facets};
    if(path==='/api/overview') return {status:200,body:DB.overview};
    if(path==='/api/signals') return {status:200,body:handleSignals(sp)};
    if(path==='/api/cases') return {status:200,body:handleCases(sp)};
    if(path==='/api/articles') return {status:200,body:handleArticles(sp)};
    var m=path.match(/^\/api\/articles\/(.+)$/);
    if(m){var d=DB.articleDetails[decodeURIComponent(m[1])];
      if(d) return {status:200,body:d};
      return {status:404,body:{error:'not found'}};}
    return null;
  }
  var origFetch=window.fetch.bind(window);
  window.fetch=function(input,init){
    var urlStr=(typeof input==='string')?input:(input&&input.url);
    try{
      var u=new URL(urlStr,window.location.href);
      if(u.origin===window.location.origin&&u.pathname.indexOf('/api/')===0){
        var r=route(u.pathname,u.searchParams);
        if(r) return Promise.resolve(new Response(JSON.stringify(r.body),
          {status:r.status,headers:{'content-type':'application/json'}}));
      }
    }catch(e){}
    return origFetch(input,init);
  };
})();
